insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-a1-11449769cd20', 'en', 'A1', 'Subject Pronouns and the Verb To Be', 'Em inglês, os subject pronouns (pronomes pessoais do caso reto) são essenciais e devem ser usados antes do verbo ''to be'' (ser/estar). Diferente do português, onde muitas vezes não precisamos falar o pronome (''sou professor''), em inglês sempre usamos o pronome: ''I am a teacher''.', 'O verbo ''to be'' tem três formas no presente: am, is, are. A escolha depende do pronome:

- I am (eu sou/estou)
- You are (você/vocês é/são, ou tu és) - sempre ''are''
- He/She/It is (ele/ela/isto é/está)
- We are (nós somos/estamos)
- They are (eles/elas são/estão)

Formas contraídas: I''m, you''re, he''s, she''s, it''s, we''re, they''re.', '["Falar sobre identidade: I am Ana. / I''m Ana.","Falar sobre origem: They are from Brazil. / They''re from Brazil.","Descrever sentimentos: She is happy. / She''s happy.","Falar sobre idade: He is 20 years old. / He''s 20.","Falar sobre localização: We are at home. / We''re at home.","Falar sobre profissões: You are a teacher. / You''re a teacher."]'::jsonb, '["Usar ''is'' com ''you'': ''You is'' (errado). O correto é ''You are''.","Usar ''are'' com ''I'': ''I are'' (errado). O correto é ''I am''.","Esquecer o pronome: ''Am a student'' (errado). O correto é ''I am a student''.","Confundir ''it''s'' (it is) com ''its'' (dele/dela). Para A1, foque em ''it''s''."]'::jsonb, '["Em inglês, o pronome sujeito nunca é omitido em frases afirmativas.","''You'' pode ser usado para uma ou várias pessoas; a forma do verbo é sempre ''are''.","''They'' pode ser usado para pessoas e também para coisas no plural.","''It'' é usado para objetos, animais e fatos.","Use as contrações em conversas informais e na fala: I''m, you''re, he''s, etc."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

