insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-a1-8a5b0514fbd0', 'en', 'A1', 'Subject Pronouns and the Verb To Be', 'Nesta lição, você vai aprender os pronomes pessoais em inglês (I, you, he, she, it, we, they) e como usá-los com o verbo to be no presente. Vamos focar em frases simples do dia a dia.', 'No presente do verbo to be, usamos ''am'' com I, ''is'' com he/she/it e ''are'' com you, we, they. Exemplos: I am Maria; You are a student; He is tall; It is a book; We are friends; They are happy. Contrações comuns: I''m, you''re, he''s, she''s, it''s, we''re, they''re.', '["Para identificar alguém ou algo: I am Ana, This is my dog.","Para falar de nacionalidade ou profissão: She is Brazilian, They are doctors.","Para descrever sentimentos ou estados: He is tired, We are hungry.","Para falar de idade: I am 30 years old.","Para falar de localização: It is on the table, They are at school."]'::jsonb, '["Esquecer o pronome: dizer ''Is teacher'' em vez de ''She is a teacher''.","Usar ''is'' com ''you'': ''You is my friend'' em vez de ''You are my friend''.","Confundir ''it''s'' (it is) com ''its'' (dele/dela) – mas isso é mais avançado.","Omitir o verbo: ''She happy'' em vez de ''She is happy''.","Trocar ''are'' por ''is'' com ''we'' e ''they'': ''We is here'' em vez de ''We are here''."]'::jsonb, '["Em inglês, o pronome sujeito é obrigatório na frase.","As contrações são comuns na fala: I''m, you''re, he''s, she''s, it''s, we''re, they''re.","O pronome ''you'' é usado tanto para singular quanto plural.","O pronome ''they'' pode ser usado para pessoas, objetos e animais.","As perguntas invertem a ordem: Am I? Are you? Is he? etc.","A negativa é formada com not: I am not, you are not, he is not.","Na negativa, também há contrações: I''m not, you aren''t, he isn''t."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

