insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-a1-b11c14ddc7a3', 'en', 'A1', 'Verb to Be and Subject Pronouns', 'Nesta lição, você vai aprender os pronomes pessoais (subject pronouns) e o verbo to be no presente. Esse verbo é essencial para se apresentar, descrever pessoas e falar de origens e sentimentos.', 'O verbo to be no presente tem três formas: am (com I), is (com he, she, it) e are (com you, we, they). Veja: I am / I''m, You are / You''re, He is / He''s, She is / She''s, It is / It''s, We are / We''re, They are / They''re. Na forma negativa, usamos not: am not, is not (isn''t), are not (aren''t). Nas perguntas, invertemos: Am I...? Is he...? Are you...?', '["Para identificar ou apresentar alguém: I am Ana. / She is my friend.","Para descrever características: He is tall. / They are nice.","Para falar de origem ou nacionalidade: We are from Brazil. / She is Brazilian.","Para falar de profissão: I am a teacher. / He is a doctor.","Para falar de idade: I am 25 years old.","Para falar de estado ou sentimento: She is happy. / They are tired."]'::jsonb, '["Usar ''is'' com ''you'': o correto é You are.","Esquecer o verbo: ''She my sister'' -> She is my sister.","Usar ''do'' para perguntas com to be: o correto é Are you...? e não Do you are...?","Confundir he/she para objetos: usamos it para coisas e animais."]'::jsonb, '["As contrações são muito comuns na fala e na escrita informal: I''m, you''re, he''s, etc.","''You'' é usado tanto para uma pessoa quanto para várias; o verbo continua are.","''It'' pode ser usado para o tempo e clima: It is hot.","Na forma negativa, ''isn''t'' e ''aren''t'' são mais comuns que as formas completas."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

