insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-a1-a5e7bd87a40a', 'en', 'A1', 'Subject Pronouns with Be (Present)', 'Nesta lição, você vai aprender os pronomes sujeito em inglês (I, you, he, she, it, we, they) e como usar o verbo ''to be'' (ser/estar) no presente. Isso é essencial para se apresentar, falar sobre nacionalidades, profissões e sentimentos.', 'O verbo ''to be'' tem três formas no presente: am, is, are. Use ''am'' com I, ''is'' com he, she, it, e ''are'' com you, we, they. Exemplos: I am a teacher. She is a doctor. They are friends.', '["Para se apresentar e falar sobre profissão: I am a student.","Para falar sobre nacionalidade e origem: She is from Brazil.","Para descrever pessoas e lugares: He is tall. It is beautiful.","Para falar sobre sentimentos e estados: We are happy. They are tired."]'::jsonb, '["Usar ''is'' com ''I'': I is → I am. Nunca use ''is'' com ''I''.","Esquecer o verbo: ''She teacher'' → ''She is a teacher''. O verbo é obrigatório.","Confundir ''you'' singular e plural: Use ''are'' para ambos. You are my friend (você) / You are my friends (vocês)."]'::jsonb, '["Em inglês, o pronome ''it'' é usado para coisas, animais e objetos. Diferente do português, não usamos ''ele/ela'' para objetos.","O pronome ''they'' é usado para pessoas, coisas e animais no plural.","Na forma negativa, adicione ''not'' depois do verbo: I am not, he is not, they are not. Na forma contraída: isn''t, aren''t."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

