insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-a1-b2b9aba6e512', 'en', 'A1', 'Subject Pronouns and Verb To Be (Present)', 'Nesta lição, você vai aprender os pronomes pessoais (I, you, he, she, it, we, they) e o verbo ''to be'' (ser/estar) no presente. Esse verbo é fundamental para se apresentar, falar de origens, descrever pessoas e indicar lugares. Em inglês, o verbo ''to be'' nunca pode ser omitido.', 'O verbo ''to be'' muda de forma conforme o sujeito:
I am (I''m) – eu sou/estou
You are (You''re) – você é/está
He is (He''s) – ele é/está
She is (She''s) – ela é/está
It is (It''s) – isso é/está
We are (We''re) – nós somos/estamos
They are (They''re) – eles/elas são/estão

Negativa: I am not (I''m not), You are not (You aren''t), He/She/It is not (isn''t), We/They are not (aren''t).

Pergunta: Are you...? Is he/she/it...? Are we/they...? O verbo vem antes do sujeito.', '["Falar nome e profissão: ''I am a teacher.''","Falar origem: ''She is from Brazil.''","Descrever características: ''They are happy.''","Falar idade: ''He is 25 years old.''","Falar localização: ''We are in São Paulo.''","Identificar pessoas e coisas: ''It is a book.''"]'::jsonb, '["Usar ''I is'' em vez de ''I am''.","Usar ''She are'' em vez de ''She is''.","Esquecer o verbo: ''I student'' em vez de ''I am a student''.","Escrever ''is''nt'' em vez de ''isn''t''.","Usar ''am'' com ''he'', ''she'' ou ''it''."]'::jsonb, '["''You'' é usado tanto para uma pessoa quanto para várias.","O verbo ''to be'' é sempre necessário em inglês.","As contrações são comuns: I''m, you''re, he''s, she''s, it''s, we''re, they''re.","Na negativa, ''am not'' não tem contração; usamos ''I''m not''.","Nas perguntas, a ordem é Verbo + Sujeito: ''Are you...?''","Use ''it'' para objetos, animais e coisas."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

