insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-a1-3aa86a610b04', 'en', 'A1', 'Subject Pronouns and the Verb ''To Be''', 'Nesta lição, você vai estudar os pronomes pessoais (I, you, he, she, it, we, they) e o verbo ''to be'' (ser/estar) no presente. Esse é um dos primeiros passos para formar frases simples em inglês, como se apresentar, falar sobre origem e descrever pessoas.', 'O verbo ''to be'' tem três formas no presente: am, is e are. Use ''am'' com I; ''is'' com he, she, it; e ''are'' com you, we e they. Exemplos: I am a student. She is a teacher. They are friends. As contrações são: I''m, you''re, he''s, she''s, it''s, we''re, they''re.', '["Apresentar-se: I am Ana. (Eu sou Ana.)","Falar sobre profissão: He is a doctor. (Ele é médico.)","Falar sobre origem: They are from Brazil. (Eles são do Brasil.)","Descrever pessoas ou coisas: She is tall. (Ela é alta.) It is small. (É pequeno.)","Falar sobre estado ou emoção: We are happy. (Estamos felizes.)","Dizer a idade: I am 30 years old. (Eu tenho 30 anos.)"]'::jsonb, '["Usar ''is'' com ''I'': o correto é ''I am''.","Usar ''are'' com ''he'', ''she'' ou ''it'': o correto é ''is''.","Esquecer o pronome antes do verbo: ''Is a teacher'' → ''He is a teacher''.","Confundir ''you'' singular e plural: em ambos os casos o verbo é ''are''."]'::jsonb, '["Em inglês, o pronome ''you'' pode ser ''você'' ou ''vocês''.","O pronome ''it'' é usado para coisas, animais e às vezes para bebês.","Use as contrações em conversas informais: I''m, you''re, he''s, she''s, it''s, we''re, they''re.","Para formar perguntas, coloque o verbo antes do pronome: ''You are a student'' → ''Are you a student?''.","A forma negativa é feita com ''not'' depois do verbo: I am not, you are not, he is not."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

