insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-a1-3e36c5b28457', 'en', 'A1', 'Subject Pronouns and Verb To Be', 'Nesta lição, você vai aprender os subject pronouns (pronomes sujeito) em inglês e o verbo to be no presente. Esses são a base para formar frases simples como ''I am a teacher'' ou ''She is from Brazil''.', 'Subject pronouns: I, you, he, she, it, we, they. Verbo to be: I am, you are, he/she/it is, we are, they are. Formas contraídas: I''m, you''re, he''s, she''s, it''s, we''re, they''re.', '["Usamos ''I'' para falar de nós mesmos: I am happy. (Eu estou feliz.)","Usamos ''you'' para a pessoa com quem falamos: You are my friend. (Você é meu amigo.)","Usamos ''he'' para homem, ''she'' para mulher e ''it'' para coisas ou animais: The cat is small. It is small.","Usamos ''we'' para um grupo que inclui a pessoa que fala: We are students. (Nós somos estudantes.)","Usamos ''they'' para várias pessoas ou coisas: They are from Brazil. (Eles são do Brasil.)"]'::jsonb, '["Não confundir ''you'' (você/vocês) com ''he/she''.","Não usar ''he'' para coisas; use ''it''.","Não esquecer o verbo: ''I teacher'' está errado; o correto é ''I am a teacher''.","Não trocar ''am'' por ''is'': ''I is'' é errado."]'::jsonb, '["Em inglês, o pronome sujeito é sempre necessário, diferente do português.","Contrações são comuns na fala: I''m, you''re, he''s.","''You'' é usado tanto para uma pessoa quanto para várias.","''It'' também é usado para o tempo, clima e hora: It is hot."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

