insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-a1-d0452ae6db47', 'en', 'A1', 'Subject Pronouns and the Verb ''To Be''', 'Os pronomes pessoais em inglês são usados para substituir nomes e são essenciais com o verbo ''to be'' (ser/estar). Nesta lição, você vai aprender a combinar I, you, he, she, it, we, they com as formas am, is, are para fazer frases simples.', 'O verbo ''to be'' tem três formas no presente: am (com I), is (com he, she, it) e are (com you, we, they). Use contrações na fala e na escrita informal: I''m, you''re, he''s, she''s, it''s, we''re, they''re.', '["Apresentar-se: I am Ana.","Falar sobre origem: She is from Brazil.","Descrever pessoas: He is tall.","Falar sobre profissões: They are teachers.","Indicar localização: We are at home."]'::jsonb, '["Dizer ''I is'' em vez de ''I am''.","Usar ''is'' com ''you'': ''You is'' → ''You are''.","Usar ''are'' com ''he/she/it'': ''She are'' → ''She is''.","Esquecer o verbo: ''I student'' → ''I am a student''."]'::jsonb, '["''You'' é usado para uma ou mais pessoas em inglês.","''It'' é usado para coisas, animais e também para clima/tempo.","As contrações são muito comuns na fala e na escrita informal."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

