insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-a1-177536f127d2', 'en', 'A1', 'Subject Pronouns and the Verb ''To Be'' (Present)', 'Este guia apresenta os pronomes pessoais (subject pronouns) e o verbo ''to be'' (ser/estar) no presente. Você vai aprender a usar I, you, he, she, it, we, they com am, is e are.', 'Formação:
- I am (eu sou/estou) → I''m
- You are (você é/está) → You''re
- He/She/It is (ele/ela é/está) → He''s, She''s, It''s
- We are (nós somos/estamos) → We''re
- They are (eles/elas são/estão) → They''re

Negativa: I am not (I''m not), you are not (you aren''t), he/she/it is not (isn''t), we/they are not (aren''t).

Perguntas: Are you...? Is he...? Am I...?', '["Identificação: I am Lucas.","Origem/nacionalidade: She is from Portugal.","Profissão: They are teachers.","Estado/emoção: We are happy.","Idade: He is thirty years old."]'::jsonb, '["I is – O correto é I am.","She are – Use she is.","You is – You sempre usa are.","We am – Use we are.","He no is – Em inglês, a negativa é He isn''t ou He is not."]'::jsonb, '["You é usado para ''você'' e ''vocês''.","It refere-se a coisas, animais e lugares.","Contrações são muito comuns na fala: I''m, she''s, they''re.","Em inglês, use ''to be'' para idade: I am 25 (não ''I have 25'').","A ordem da pergunta coloca o verbo antes do sujeito: Are you...?"]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

