insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-a1-8d387f64f57f', 'en', 'A1', 'Subject Pronouns and the Verb To Be', 'Neste tópico, você vai aprender os pronomes pessoais (I, you, he, she, it, we, they) e o verbo to be no presente (am, is, are). Eles são essenciais para se apresentar, falar sobre profissões, nacionalidades, emoções e lugares.', 'O verbo to be muda com o pronome: I am, You are, He/She/It is, We are, You are, They are. Formas contraídas: I''m, you''re, he''s, she''s, it''s, we''re, they''re. Na forma negativa, usamos ''not'': I am not, you are not, he/she/it is not, we are not, they are not. Na forma interrogativa, invertemos: Am I? Are you? Is he? etc.', '["Identidade: I am Carla.","Nacionalidade: She is Brazilian.","Profissão: He is a doctor.","Localização: We are at home.","Descrição/estado: They are happy.","Idade: I am 25 years old."]'::jsonb, '["Usar ''are'' com he/she/it: ''She are nice'' (incorreto; correto: She is nice).","Usar ''am'' com he/she/it: ''He am tall'' (incorreto; correto: He is tall).","Esquecer o verbo: ''I student'' (incorreto; correto: I am a student).","Confundir ''your'' com ''you''re'': ''Your are my friend'' (incorreto; correto: You''re my friend)."]'::jsonb, '["''You'' pode ser usado para ''você'' e ''vocês''.","''It'' é usado para coisas e animais.","Em português, muitas vezes não usamos o pronome (ex: ''sou professora''), mas em inglês sempre usamos."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

