insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-a1-b3c80f55a9de', 'en', 'A1', 'Subject Pronouns and the Verb ''to be''', 'Nesta lição, você vai aprender os pronomes pessoais em inglês (I, you, he, she, it, we, they) e como usar o verbo ''to be'' (ser/estar) no presente. Esse é um dos primeiros passos para formar frases simples em inglês.', 'A forma afirmativa do verbo ''to be'' é: I am, You are, He/She/It is, We are, They are. As contrações comuns são: I''m, you''re, he''s, she''s, it''s, we''re, they''re. Para negar, usamos ''not'': I am not, You are not, He/She/It is not, We are not, They are not. Nas perguntas, invertemos: Am I? Are you? Is he/she/it? Are we? Are they?', '["Identificar ou apresentar pessoas: ''I am Ana.'' / ''This is my friend.''","Descrever características: ''She is tall.'' / ''They are nice.''","Falar sobre origem ou nacionalidade: ''He is from Brazil.'' / ''We are Brazilian.''","Falar sobre profissão: ''I am a teacher.'' / ''You are a student.''","Falar sobre idade: ''She is 25.'' / ''I am 30.''","Falar sobre estado ou sentimento: ''We are happy.'' / ''It is cold.''"]'::jsonb, '["''I is'' — o correto é ''I am''.","''She are'' — com ''she'' usamos ''is''.","''Is you'' — com ''you'' usamos ''Are you''?","''He don''t'' — com ''he'' usamos ''is not'' (isn''t) para o verbo ''to be''."]'::jsonb, '["O pronome ''you'' é usado para ''você'' e ''vocês''.","As contrações ''I''m'', ''you''re'', ''he''s'' etc. são muito comuns na fala.","Não existe ''I amn''t''. Use ''I''m not''.","Na forma interrogativa, invertemos o verbo e o pronome: ''Are you...?'' / ''Is she...?''","''It'' é usado para coisas, animais e frases impessoais, como ''It is hot.''"]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

