insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-a1-1ab58422f29b', 'en', 'A1', 'Subject Pronouns + Verb BE', 'Nesta lição, você vai aprender os subject pronouns (I, you, he, she, it, we, they) e o verbo BE (am, is, are) no presente. Essas estruturas são fundamentais para formar frases simples para se apresentar, falar origem, profissões e sentimentos.', 'O verbo BE tem três formas: am (com I), is (com he, she, it) e are (com you, we, they). Na forma afirmativa: I am, you are, he is, she is, it is, we are, they are. As contrações são: I''m, you''re, he''s, she''s, it''s, we''re, they''re. Na negativa, adicione not: I am not, you are not, he is not, etc. Para perguntas, inverta: Am I? Are you? Is he? etc.', '["Para se apresentar: I am Carla.","Para falar origem: They are from Brazil.","Para profissões: He is an engineer.","Para estados e sentimentos: We are happy.","Para localização: It is near the park."]'::jsonb, '["Dizer ''I is'' em vez de ''I am''.","Usar ''am'' com he/she/it: ''She am tired'' (errado).","Esquecer o pronome: ''Is from Brazil'' em vez de ''She is from Brazil''.","Usar ''are'' com he/she/it: ''She are my sister'' (errado).","Confundir ''your'' com ''you''re'': ''Your happy'' em vez de ''You''re happy''."]'::jsonb, '["O verbo BE é irregular. Memorize: I am, you are, he/she/it is, we/you/they are.","As contrações são comuns na fala e em mensagens informais.","Na negativa, ''is not'' pode ser ''isn''t'' e ''are not'' pode ser ''aren''t''.","Em perguntas, o verbo vem antes do sujeito: ''Is she your friend?''","Use ''it'' para coisas, animais e clima: ''It is hot.''"]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

