insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-a1-9997e2500fa9', 'en', 'A1', 'Subject Pronouns with the Verb To Be', 'Nesta lição, você vai aprender os subject pronouns (pronomes sujeito) em inglês e como usá-los com o verbo to be (ser/estar) no presente. Isso é essencial para formar frases simples como ''I am a teacher'' ou ''She is from Brazil''.', 'Os subject pronouns são: I (eu), you (você/vocês), he (ele), she (ela), it (ele/ela para coisas ou animais), we (nós), they (eles/elas). Com o verbo to be, usamos: I am, you are, he/she/it is, we are, they are. Na forma negativa: I am not, you are not, he/she/it is not, we are not, they are not. As contrações comuns: I''m, you''re, he''s, she''s, it''s, we''re, they''re; isn''t (is not) e aren''t (are not).', '["Para se apresentar: I am Maria. / Eu sou Maria.","Para falar nacionalidade: They are Brazilian. / Eles são brasileiros.","Para dizer profissão: He is a doctor. / Ele é médico.","Para descrever pessoas ou coisas: It is big. / É grande.","Para falar de idade: She is 30 years old. / Ela tem 30 anos.","Para indicar localização: We are at home. / Estamos em casa."]'::jsonb, '["Não use ''is'' com ''you'': o correto é ''you are'', não ''you is''.","Não esqueça o pronome antes do verbo: em inglês, dizemos ''She is nice'', não ''Is nice''.","Em português, às vezes omitimos o pronome, mas em inglês ele é obrigatório: ''I am tired'', não ''Am tired''.","Não use ''he'' para objetos: para coisas e animais, use ''it''."]'::jsonb, '["Em inglês, não existe a distinção entre ''tu'' e ''você'' para o pronome you; ele é usado para ambos.","O pronome ''it'' é usado para coisas, animais e também para o tempo e clima: It is hot.","As contrações são muito comuns na fala e na escrita informal: I''m, you''re, he''s, etc.","Em perguntas, invertemos o verbo e o pronome: Are you a student? / Você é estudante?"]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

