values ('generated-grammar-en-a1-9997e2500fa9-exercise-01', 'en', 'A1', 'Exercício 1', 'Usamos o pronome ''I'' para falar de nós mesmos. A frase correta é ''I am from Brazil'' (Eu sou do Brasil).', 'Complete the sentence: "I am from Brazil."', 'Complete the sentence: "___ am from Brazil."', '["You","I","She","They"]'::jsonb, 1, 1, true, 'generated-grammar-en-a1-9997e2500fa9')
