insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-a1-d61c3c5a73c4', 'en', 'A1', 'Subject Pronouns and the Verb ''To Be''', 'Nesta lição, você vai aprender os pronomes pessoais do inglês (I, you, he, she, it, we, they) e como usar o verbo ''to be'' (ser/estar) no presente. Esses pronomes são essenciais para formar frases simples como ''I am a teacher'' e ''She is Brazilian''.', 'O verbo ''to be'' tem três formas no presente: am para ''I'', is para he/she/it, e are para you/we/they. A estrutura básica é: pronome + verbo + complemento. Exemplos: I am Ana. You are my friend. He is from Brazil. It is a book. We are students. They are happy.', '["Apresentar-se: I am Carlos. / I''m Carlos.","Dizer nacionalidades e origens: She is Brazilian. / They are from São Paulo.","Descrever pessoas e coisas: He is tall. / It is new.","Falar sobre estados e sentimentos: We are tired. / They are happy."]'::jsonb, '["Usar ''is'' com ''I'': *I is tired. → I am tired.","Esquecer o verbo: *She Brazilian. → She is Brazilian.","Confundir ''you'' singular e plural: ''you'' serve para os dois e sempre usa ''are''.","Usar ''am'' com ''he/she/it'': *He am my brother. → He is my brother."]'::jsonb, '["No inglês falado, usamos contrações: I''m, you''re, he''s, she''s, it''s, we''re, they''re.","Em perguntas, invertemos o verbo e o pronome: Are you a student? Yes, I am.","''It'' é usado para coisas, animais e impessoal: It is raining."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

