insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-a1-ac1522a3f1a9', 'en', 'A1', 'Subject Pronouns with the Verb ''To Be''', 'Nesta lição, você vai aprender os pronomes pessoais em inglês e como usá-los com o verbo ''to be''. Esses pronomes são usados como sujeito da frase, ou seja, quem faz a ação. Em português, temos ''eu'', ''você'', ''ele'', ''ela'', ''nós'' e ''eles''. Em inglês, usamos I, you, he, she, it, we e they. Vamos ver como formar frases simples e corretas.', 'Use os pronomes com as formas do verbo ''to be'': I am, you are, he is, she is, it is, we are, they are. As formas contraídas são comuns na fala: I''m, you''re, he''s, she''s, it''s, we''re, they''re. Exemplos: I am a teacher. = Eu sou professor(a). You are a student. = Você é estudante. She is happy. = Ela está feliz.', '["Apresentar-se: I am Ana. / I''m Ana.","Falar sobre nacionalidade ou origem: They are from Brazil. / She is from Portugal.","Descrever pessoas e coisas: He is tall. / It is big.","Falar sobre profissões: We are teachers. / You are a student.","Falar sobre estados ou sentimentos: I am happy. / They are tired."]'::jsonb, '["Usar ''is'' com ''I'': ''I is'' está errado. O correto é ''I am''.","Esquecer o pronome antes do verbo: ''Is teacher'' em vez de ''He is a teacher''.","Usar ''are'' com ''he/she/it'': ''She are'' está errado. Use ''She is''.","Traduzir ''você'' como ''you'' e usar ''is'': ''You is'' está errado. Use ''You are''."]'::jsonb, '["Em inglês, o pronome ''it'' é usado para coisas, animais e também para o clima ou tempo.","O pronome ''you'' serve para uma ou mais pessoas. O verbo não muda: You are.","As contrações são comuns na fala: I''m, you''re, he''s, she''s, it''s, we''re, they''re.","Em frases negativas, use ''not'' depois do verbo: He is not tired. / He isn''t tired."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

