insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-a1-de6c53d1601c', 'en', 'A1', 'Subject Pronouns with Be (Present Simple)', 'Nesta lição, você vai aprender os subject pronouns (pronomes sujeito) em inglês e como usá-los com o verbo to be (ser/estar) no presente. Isso é essencial para formar frases básicas como I am a teacher ou She is from Brazil.', 'Com o verbo to be no presente, cada pronome sujeito tem uma forma específica: I am (eu sou/estou), you are (você é/está), he/she/it is (ele/ela/é/está), we are (nós somos/estamos) e they are (eles/elas são/estão). As formas contraídas são muito usadas na fala: I''m, you''re, he''s, she''s, it''s, we''re, they''re.', '["Para identificar pessoas: I am Ana. (Eu sou Ana.)","Para falar de origem: You are from Brazil. (Você é do Brasil.)","Para descrever coisas: It is a book. (É um livro.)","Para falar de grupos: We are students. (Nós somos estudantes.)"]'::jsonb, '["Dizer He are em vez de He is.","Usar is com I: I is em vez de I am.","Esquecer o pronome sujeito: Is a teacher em vez de He is a teacher.","Confundir you are com your."]'::jsonb, '["You é usado para o singular e o plural.","It é usado para coisas, animais e ideias.","As contrações são comuns na comunicação informal: I''m, you''re, he''s, etc."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

