insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-a1-3cfc9f6da575', 'en', 'A1', 'Subject Pronouns and the Verb ''To Be''', 'Nesta lição, você vai aprender os pronomes pessoais em inglês: I, you, he, she, it, we, they. Vai também aprender o presente do verbo ''to be'' (am, is, are), que é muito usado para falar de identidade, nacionalidade, profissão, localização e sentimentos.', 'O verbo ''to be'' no presente tem três formas: am (com I), is (com he, she, it) e are (com you, we, they). Exemplos: I am = I''m; you are = you''re; he is = he''s; she is = she''s; it is = it''s; we are = we''re; they are = they''re. Na negativa, adicione ''not'': I am not, you are not (you aren''t), he is not (he isn''t), we are not (we aren''t), they are not (they aren''t).', '["Introducing yourself: ''I am Beatriz.''","Talking about nationality: ''They are Brazilian.''","Saying your age: ''She is 30 years old.''","Describing people or things: ''It is a book.''","Talking about location: ''We are in São Paulo.''"]'::jsonb, '["''I is'' – always use ''am'' with ''I''.","''She are'' – use ''is'' with he/she/it.","''You is'' – use ''are'' with ''you''.","Forgetting the verb: ''I teacher'' → ''I am a teacher.''"]'::jsonb, '["''You'' pode ser usado para uma pessoa ou várias pessoas.","''It'' é usado para objetos, animais e ideias sem gênero.","''They'' pode se referir a pessoas e coisas no plural.","As contrações são comuns em inglês falado e informal.","Na negativa, ''aren''t'' e ''isn''t'' são muito usados."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

