insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-a1-9dd3bbb6e45b', 'en', 'A1', 'Pronomes Pessoais e o Verbo To Be', 'Nesta lição, você vai aprender os pronomes pessoais em inglês (I, you, he, she, it, we, they) e como usá-los com o verbo ''to be'' (am, is, are) no presente. Em inglês, o pronome é sempre obrigatório antes do verbo, diferente do português.', 'O verbo ''to be'' no presente tem três formas: am, is, are. Use ''am'' com I, ''is'' com he/she/it, e ''are'' com you/we/they. Exemplos: I am Paulo (Eu sou Paulo), She is a doctor (Ela é médica), We are friends (Nós somos amigos). Formas contraídas: I''m, you''re, he''s, she''s, it''s, we''re, they''re. Formas negativas: I''m not, you aren''t, he isn''t, etc.', '["Para identificar alguém: I am Ana.","Para dizer origem ou nacionalidade: They are from Brazil.","Para falar de profissão: He is a teacher.","Para descrever um estado: We are happy."]'::jsonb, '["Omitir o pronome: ''Is doctor'' em vez de ''He is a doctor''.","Usar ''is'' com I: ''I is'' em vez de ''I am''.","Usar ''am'' com he/she/it: ''He am'' em vez de ''He is''.","Confundir ''are'' com ''is'' no plural: ''They is'' em vez de ''They are''."]'::jsonb, '["O pronome ''it'' é usado para coisas, animais e objetos.","You é usado tanto para ''você'' quanto para ''vocês''.","As contrações (I''m, she''s) são comuns na conversação e na escrita informal."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

