insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-a1-5b7f362a805b', 'en', 'A1', 'Subject Pronouns and the Verb ''Be'' (Present Simple)', 'Nesta lição, você vai aprender os pronomes pessoais em inglês (I, you, he, she, it, we, they) e como usar o verbo ''to be'' (ser/estar) no presente. Vamos ver como formar frases afirmativas, negativas e perguntas simples.', 'O verbo ''to be'' tem três formas no presente: am, is, are. Use ''am'' com I; ''is'' com he, she, it; ''are'' com you, we, they. Exemplos: I am happy. She is a doctor. They are students. Forma negativa: coloque ''not'' depois do verbo: I am not tired. He is not (isn''t) here. We are not (aren''t) at home. Perguntas: inverta o verbo e o sujeito: Are you ok? Is he your brother? Note que ''you'' é usado para você e vocês.', '["Apresentar-se: I am Ana. / I''m Ana.","Falar sobre profissões: He is a teacher.","Descrever características: They are friendly.","Falar sobre origem: We are from Brazil.","Indicar localização: The cat is under the table.","Falar sobre idade: She is 25 years old."]'::jsonb, '["Usar ''is'' com I: I is happy. O correto é I am happy.","Dizer ''I student'' sem verbo. Lembre-se: I am a student.","Usar ''he'' para objetos: The book is new. Dizer ''He is new'' é errado para objeto.","Formar perguntas sem inverter: ''You are ready?'' O correto é ''Are you ready?''","Confundir ''you'' singular e plural: ''You are'' serve para os dois."]'::jsonb, '["O verbo ''to be'' é irregular; é essencial memorizar suas formas.","As contrações são comuns na fala: I''m, you''re, he''s, she''s, it''s, we''re, they''re.","Em perguntas informais, a entonação pode indicar que é pergunta, mas na escrita use a inversão.","Use ''it'' para animais, objetos e coisas: It is a dog. It is a book.","Cuidado com a terceira pessoa: ''he'' para homens, ''she'' para mulheres, ''it'' para o resto."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

