insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-a1-d6a24c19cf02', 'en', 'A1', 'Subject Pronouns and the Verb ''To Be''', 'Nesta lição, você vai aprender os pronomes sujeito em inglês (I, you, he, she, it, we, they) e como usar o verbo ''to be'' (ser/estar) no presente. Esse é o verbo mais importante para começar a formar frases simples.', 'No presente, o verbo ''to be'' muda com o pronome: ''I am'' (eu sou/estou), ''You are'' (você é/está), ''He is'' (ele é/está), ''She is'' (ela é/está), ''It is'' (ele/ela para coisas ou animais), ''We are'' (nós somos/estamos) e ''They are'' (eles/elas são/estão). As formas contraídas são comuns: I''m, you''re, he''s, she''s, it''s, we''re, they''re.', '["Usamos para identificar pessoas: ''I am Maria.''","Usamos para falar de origem ou nacionalidade: ''You are Brazilian.''","Usamos para descrever profissões: ''He is a teacher.''","Usamos para indicar localização: ''We are at home.''"]'::jsonb, '["Não diga ''I is''. O correto é ''I am''.","Não esqueça o verbo: ''She teacher'' está errado; use ''She is a teacher''.","Não use ''you is''. O correto é ''you are''.","Não use ''they is''. O correto é ''they are''."]'::jsonb, '["O pronome ''you'' pode significar ''você'' ou ''vocês''.","Use ''it'' para coisas, lugares e animais.","As contrações são muito usadas na fala: I''m, you''re, he''s, etc.","Na negativa, usamos ''not'': ''I am not'', ''you are not'', etc."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

