insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-a1-eb3692a741b2', 'en', 'A1', 'Subject Pronouns in English', 'Nesta lição, você vai aprender os pronomes pessoais do caso reto em inglês: I, you, he, she, it, we e they. Eles são usados como sujeito da frase, ou seja, para indicar quem faz a ação. Em português, temos eu, você, ele, ela, nós, eles/elas. Vamos ver como usar cada um com exemplos simples.', 'Os subject pronouns em inglês são:

I = eu
You = você / vocês
He = ele (para homem ou animal macho)
She = ela (para mulher ou animal fêmea)
It = ele/ela para coisas, animais e ideias
We = nós
They = eles / elas / pessoas em geral

Exemplos:
I am Ana. = Eu sou Ana.
You are a student. = Você é estudante.
He is my brother. = Ele é meu irmão.
She is from Brazil. = Ela é do Brasil.
It is a dog. = (Ele) é um cachorro.
We are friends. = Nós somos amigos.
They are teachers. = Eles são professores.', '["I: para falar de si mesmo. Ex.: I like coffee.","You: para falar com uma pessoa ou com várias pessoas. Ex.: You are welcome.","He: para falar de um homem. Ex.: He is tall.","She: para falar de uma mulher. Ex.: She is my mother.","It: para falar de coisas, animais ou lugares. Ex.: It is a book.","We: para falar de você e outras pessoas. Ex.: We live in São Paulo.","They: para falar de outras pessoas ou coisas. Ex.: They are students."]'::jsonb, '["Não use ''He'' para coisas: ''It is a car'', não ''He is a car''.","Não esqueça o pronome antes do verbo: em inglês, dizemos ''She is happy'', não ''Is happy''.","Não confunda ''You'' singular e plural: ''You are'' serve para você e vocês.","Não use ''She'' para objetos: ''The table is big. It is big'', não ''She is big''."]'::jsonb, '["Sempre escreva ''I'' com letra maiúscula, mesmo no meio da frase.","O pronome ''It'' é usado para animais quando não sabemos o sexo.","Em inglês, não existe distinção de gênero para ''you''.","Use ''They'' também para um grupo de coisas e pessoas.","O verbo ''to be'' muda de forma com cada pronome: I am, you are, he/she/it is, we are, they are."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

