insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-a1-9bc35a7b9928', 'en', 'A1', 'Subject Pronouns and the Verb To Be', 'Nesta lição, você vai aprender os pronomes sujeito em inglês (I, you, he, she, it, we, they) e como usar o verbo ''to be'' (ser/estar) no presente. Isso é essencial para se apresentar, falar sobre profissões, nacionalidades e sentimentos.', 'O verbo ''to be'' muda de acordo com o pronome:

- I am (eu sou/estou)
- You are (você é/está)
- He/She/It is (ele/ela/isto é/está)
- We are (nós somos/estamos)
- They are (eles/elas são/estão)

As formas contraídas são comuns: I''m, you''re, he''s, she''s, it''s, we''re, they''re.', '["Para se identificar: ''I am Ana.''","Para dizer a nacionalidade: ''They are Brazilian.''","Para falar da profissão: ''He is a doctor.''","Para descrever sentimentos: ''She is happy.''","Para indicar lugar: ''We are here.''"]'::jsonb, '["Dizer ''I is'' em vez de ''I am''.","Dizer ''She are'' em vez de ''She is''.","Esquecer o verbo: ''She doctor'' em vez de ''She is a doctor''.","Usar ''am'' com ''he'': ''He am'' em vez de ''He is''.","Confundir ''you'' singular e plural: nos dois casos usamos ''are''."]'::jsonb, '["''You'' pode significar ''você'' ou ''vocês''.","''It'' é usado para coisas, animais e também para o clima ou tempo.","As contrações são muito usadas na conversa diária.","''They'' pode se referir a pessoas, lugares ou coisas no plural.","Não se esqueça do artigo ''a'' antes de profissões: ''I am a teacher''."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

