insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-a1-c212cad819e2', 'en', 'A1', 'Subject Pronouns and the Verb To Be', 'Nesta lição, você vai aprender os pronomes sujeitos em inglês (I, you, he, she, it, we, they) e o verbo ''to be'' (ser/estar). Usamos essas palavras para falar sobre identidade, nacionalidade, profissão, idade, localização e características.', 'O verbo ''to be'' tem três formas no presente: am, is, are. A conjugação é: I am, you are, he/she/it is, we are, you are, they are. As contrações são: I''m, you''re, he''s, she''s, it''s, we''re, they''re. Para negar, usamos ''not'' após o verbo: I am not, you are not, etc.', '["Para falar quem você é: I am Carlos.","Para falar nacionalidade: She is Brazilian.","Para falar profissão: He is a doctor.","Para falar idade: I am 30 years old.","Para falar localização: We are at home.","Para descrever: It is big."]'::jsonb, '["Usar ''is'' para todas as pessoas (ex.: I is). Em inglês, use ''am'' com I.","Esquecer de usar ''are'' com you, we, they (ex.: You is).","Confundir ''he'', ''she'', ''it'' com ''he''s'', etc. Lembre-se de usar ''is'' com esses pronomes.","Traduzir literalmente do português ''eu sou'' como ''I is''."]'::jsonb, '["As contrações são muito comuns na fala e na escrita informal.","O pronome ''you'' é usado tanto para ''você'' quanto para ''vocês''.","Em perguntas, invertemos o verbo e o sujeito: ''Are you a student?''."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

