insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-a1-23eae75db75d', 'en', 'A1', 'Subject Pronouns and the Verb ''To Be'' (Present Simple)', 'Nesta lição, você vai aprender os pronomes pessoais em inglês e o verbo ''to be'' (ser/estar) no presente. Esses são os primeiros passos para formar frases simples como ''I am a teacher'' ou ''They are happy''.', 'O verbo ''to be'' tem três formas no presente: am (com I), is (com he, she, it) e are (com you, we, they). Exemplos: I am, you are, he is, she is, it is, we are, they are. As contrações comuns são: I''m, you''re, he''s, she''s, it''s, we''re, they''re.', '["Para apresentar-se: ''I am Ana.'' / ''I''m from Brazil.''","Para falar de profissões: ''He is a doctor.''","Para descrever pessoas e coisas: ''She is tall.'' / ''It is big.''","Para falar de estado ou emoção: ''We are tired.'' / ''They are happy.''","Para dizer idade: ''I am 25 years old.''"]'::jsonb, '["She are my friend. (Correto: She is my friend.)","I is tired. (Correto: I am tired.)","You is welcome. (Correto: You are welcome.)","Esquecer o verbo: He doctor. (Correto: He is a doctor.)","Usar ''have'' para idade: I have 25 years. (Correto: I am 25 years old.)"]'::jsonb, '["Em inglês, o pronome ''you'' é usado para ''você'' (singular) e ''vocês'' (plural).","O pronome ''it'' refere-se a coisas, animais e ideias, não a pessoas.","''They'' pode ser usado para pessoas, coisas e também como pronome neutro singular (uso moderno).","As contrações são muito comuns em conversas informais."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

