insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-a1-fd236cd4d285', 'en', 'A1', 'Subject Pronouns and the Verb To Be', 'Nesta lição, você vai aprender os pronomes pessoais em inglês (I, you, he, she, it, we, they) e como usar o verbo TO BE (ser/estar) no presente. Esse é um conteúdo básico para fazer apresentações, falar de nacionalidade, profissão, idade e sentimentos.', 'O verbo TO BE tem três formas no presente: am, is, are. Use am com I; use is com he, she, it; use are com you, we, they. Veja: I am (eu sou/estou), you are (você é/está), he is (ele é/está), she is (ela é/está), it is (isto é/está), we are (nós somos/estamos), they are (eles/elas são/estão).', '["Para dizer quem você é: I am Ana.","Para falar a nacionalidade: You are Brazilian.","Para falar a idade: She is twenty years old.","Para falar sentimentos: We are happy."]'::jsonb, '["Não use ''I is'' ou ''I are''. O correto é ''I am''.","Não use ''He are''. O correto é ''He is''.","Não use ''They is''. O correto é ''They are''."]'::jsonb, '["O pronome ''you'' pode ser usado para uma pessoa ou várias.","Em inglês, use ''you'' para todas as pessoas, sem tratamento formal.","Use ''it'' para objetos, animais e lugares. Exemplo: It is a book."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

