insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-a1-22916b9ef769', 'en', 'A1', 'Subject Pronouns and Verb To Be (Present Simple)', 'Nesta lição, você vai aprender os pronomes pessoais (subject pronouns) em inglês e o verbo to be no presente. Esse conteúdo é essencial para se apresentar, falar sobre origem, profissão, idade e descrever pessoas e coisas.', 'Os pronomes pessoais em inglês são: I (eu), you (você/vocês), he (ele), she (ela), it (ele/ela para coisas e animais), we (nós) e they (eles/elas). O verbo to be no presente tem formas diferentes: I am, you are, he/she/it is, we are, you are, they are. As contrações comuns são: I''m, you''re, he''s, she''s, it''s, we''re, they''re.', '["Apresentar-se: I am Anna. / I''m Anna.","Falar sobre nacionalidade ou origem: She is from Brazil.","Descrever pessoas e coisas: He is tall. It is big.","Falar sobre idade e profissão: They are students."]'::jsonb, '["Não use ''are'' com he/she/it. O correto é ''He is'', não ''He are''.","Não use ''is'' com I. O correto é ''I am'', não ''I is''.","Não use ''am'' com you. O correto é ''You are'', não ''You am''.","Lembre-se: ''your'' (seu/sua) é diferente de ''you''re'' (you are)."]'::jsonb, '["Em inglês, o pronome ''you'' é usado tanto para ''você'' quanto para ''vocês''.","Use ''it'' para objetos, animais e coisas em geral.","Contrações são muito usadas na fala e na escrita informal.","Não existe sujeito oculto em inglês: sempre usamos o pronome."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

