insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-a1-4a8a8627d3df', 'en', 'A1', 'Subject Pronouns and the Verb To Be', 'Nesta lição, você vai aprender os pronomes sujeito (subject pronouns) em inglês e como usá-los com o verbo to be (ser/estar). O verbo to be muda de forma: I am, you are, he/she/it is, we are, they are. Vamos praticar com exemplos simples e exercícios.', 'A forma afirmativa do verbo to be é:

I am (eu sou/estou)
You are (você é/está)
He is (ele é/está)
She is (ela é/está)
It is (ele/ela para coisas, animais, objetos)
We are (nós somos/estamos)
They are (eles/elas são/estão)

Use ''am'' com I, ''is'' com he/she/it e ''are'' com you, we e they.', '["Use para apresentar alguém: I am Ana. You are my friend.","Use para falar nacionalidade ou profissão: She is Brazilian. We are teachers.","Use para dizer onde alguém está ou de onde é: They are from Brazil. He is at home.","Use para descrever pessoas ou coisas: It is big. They are new."]'::jsonb, '["Não use ''is'' com I ou you. O correto é I am e you are.","Em inglês, o verbo to be é obrigatório. Não diga ''She teacher''; diga ''She is a teacher''.","Lembre que ''you'' serve para ''você'' e ''vocês''. Nas duas formas, use ''are''.","Para objetos, use ''it'', não ''he'' ou ''she''."]'::jsonb, '["Contrações: I''m, you''re, he''s, she''s, it''s, we''re, they''re.","Na negativa, use am not, are not (aren''t), is not (isn''t).","A forma interrogativa coloca o verbo antes do pronome: Are you...? Is he...?","Não confunda ''it''s'' (it is) com ''its'' (dele/dela). Em A1, focamos em ''it''s''."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

