insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-a1-b74da82a8e07', 'en', 'A1', 'Subject Pronouns and the Verb ''to be'' (A1)', 'Nesta lição, você vai aprender os pronomes pessoais em inglês (I, you, he, she, it, we, they) e como usá-los com o verbo ''to be'' (ser/estar). Esse é o primeiro passo para formar frases simples como ''I am a teacher'' ou ''She is my friend''.', 'O verbo ''to be'' muda de forma de acordo com o pronome:

- I am (eu sou/estou)
- You are (você é/está)
- He is (ele é/está)
- She is (ela é/está)
- It is (ele/ela para objetos ou animais)
- We are (nós somos/estamos)
- You are (vocês são/estão)
- They are (eles/elas são/estão)

Nas formas negativas, usamos ''not'' depois do verbo: ''I am not'', ''you are not'', ''he is not''. Nas perguntas, invertemos: ''Are you?'', ''Is he?''', '["Para dizer quem você é ou o que você faz: ''I am a student.'' (Eu sou estudante.)","Para falar sobre nacionalidade ou origem: ''They are from Brazil.'' (Eles são do Brasil.)","Para descrever pessoas ou coisas: ''She is tall.'' (Ela é alta.)","Para falar sobre idade (excepcionalmente em inglês): ''He is 30 years old.'' (Ele tem 30 anos.)"]'::jsonb, '["Usar ''are'' com ''I'': o correto é ''I am'', nunca ''I are''.","Confundir ''you'' com ''você'' no plural: ''you'' serve para uma pessoa ou várias.","Esquecer de usar o pronome antes do verbo em inglês: ''Is teacher'' em vez de ''He is a teacher''.","Usar ''is'' com ''they'': o correto é ''They are''."]'::jsonb, '["O pronome ''I'' (eu) é sempre escrito com letra maiúscula, mesmo no meio da frase.","O pronome ''you'' é o mesmo para singular e plural. O contexto indica o número.","Em inglês, o verbo ''to be'' também é usado para falar sobre sentimentos: ''I am happy.''","Contrações comuns: ''I''m'', ''you''re'', ''he''s'', ''she''s'', ''it''s'', ''we''re'', ''they''re''."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

