insert into public.grammar_exercises (id, language, level, title, explanation, example, question, options, answer_index, sort_order, is_published, topic_id)
values ('generated-grammar-en-a1-b74da82a8e07-exercise-04', 'en', 'A1', 'Exercício 4', 'Para um irmão (masculino), usamos ''he''. ''It'' é para objetos ou animais, e ''they'' é plural.', 'Which pronoun completes the sentence? "HeHe is my brother."', 'Which pronoun completes the sentence? "______ is my brother."', '["He","She","It","They"]'::jsonb, 0, 4, true, 'generated-grammar-en-a1-b74da82a8e07')
