insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-a1-8d7264a35598', 'en', 'A1', 'Subject Pronouns (Pronomes Sujeito)', 'Nesta lição, você vai aprender os pronomes pessoais do sujeito em inglês: I, you, he, she, it, we e they. Esses pronomes são usados para substituir nomes e indicar quem faz a ação.', 'Em inglês, o pronome sujeito sempre vem antes do verbo. Veja a tabela:
• I = eu
• you = você/vocês
• he = ele
• she = ela
• it = ele/ela (coisa, animal ou objeto)
• we = nós
• they = eles/elas
Exemplo: ''She is a teacher.'' (Ela é professora.)', '["Use ''I'' para falar de você mesmo: I am Brazilian.","Use ''you'' para falar com alguém: You are my friend.","Use ''he'' para um homem: He is John.","Use ''she'' para uma mulher: She is Maria.","Use ''it'' para objetos, animais e coisas: It is a book.","Use ''we'' para incluir você no grupo: We are students.","Use ''they'' para várias pessoas ou coisas: They are friends."]'::jsonb, '["Não use ''He'' com verbo ''are'' no singular. Errado: He are here. Certo: He is here.","Não use ''She'' com verbo sem ''s'' no presente simples. Errado: She work. Certo: She works.","Não esqueça o sujeito em inglês. Errado: Is raining. Certo: It is raining.","Não use ''me'' como sujeito. Errado: Me like coffee. Certo: I like coffee."]'::jsonb, '["O pronome ''you'' serve para uma pessoa ou mais de uma.","Use ''it'' para animais quando não sabemos o sexo.","Após he, she, it, o verbo no presente normalmente ganha ''s''.","Em inglês, sujeito é obrigatório, diferente do português."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

