insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-a1-39da5a394953', 'en', 'A1', 'Subject Pronouns and Verb To Be', 'Nesta lição, você vai aprender os pronomes pessoais do inglês (I, you, he, she, it, we, they) e como usar o verbo ''to be'' (ser/estar) no presente. Esse é um dos primeiros passos para formar frases simples em inglês.', 'Os pronomes pessoais são: I (eu), you (você/vocês), he (ele), she (ela), it (ele/ela para coisas, animais e lugares), we (nós) e they (eles/elas). O verbo ''to be'' tem três formas no presente: am (com I), is (com he, she, it) e are (com you, we, they). Exemplos: I am a teacher. You are a student. He is my friend. She is from Brazil. It is a cat. We are happy. They are here. As contrações são comuns: I''m, you''re, he''s, she''s, it''s, we''re, they''re.', '["Apresentar-se e apresentar outras pessoas: I am Ana. This is John. He is my friend.","Falar sobre nacionalidades e profissões: She is Brazilian. They are doctors.","Descrever características e estados: It is big. We are tired."]'::jsonb, '["Não use ''is'' com ''I'': diga ''I am'', não ''I is''.","Não use ''are'' com ''he'', ''she'' ou ''it'': use ''is''.","Lembre-se de incluir o verbo: ''She a teacher'' está errado; o correto é ''She is a teacher''.","Não confunda ''it''s'' (it is) com ''its'' (dele/dela)."]'::jsonb, '["O pronome ''you'' é usado tanto para uma pessoa quanto para várias, e sempre acompanha ''are''.","Use ''he'' para homens, ''she'' para mulheres e ''it'' para coisas, animais ou lugares.","As contrações são muito usadas em conversas informais e em textos escritos informais.","Para formar perguntas, inverta o verbo e o sujeito: ''Are you ready?''.","Para formar negativas, coloque ''not'' depois do verbo: ''I am not / you are not / he is not''."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

