insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-es-a1-6d078fb0ab39', 'es', 'A1', 'Gênero e número: artigos definidos e indefinidos em espanhol', 'Na língua espanhola, os substantivos têm gênero (masculino ou feminino) e número (singular ou plural). Os artigos definidos e indefinidos devem concordar com o substantivo. Nesta lição, você vai aprender a identificar e usar el/la/los/las e un/una/unos/unas.', 'Para o singular, usamos el com substantivos masculinos e la com femininos. No plural, los para masculinos e las para femininos. Os indefinidos são un (masculino singular), una (feminino singular), unos (masculino plural) e unas (feminino plural). Exemplos: el niño/los niños; la niña/las niñas; un perro/unos perros; una casa/unas casas.', '["Identificar pessoas e objetos no singular: ''El libro es interesante.'' / ''La casa es grande.''","Falar de mais de um elemento: ''Los libros son interesantes.'' / ''Las casas son grandes.''","Apresentar algo pela primeira vez com artigo indefinido: ''Tengo un perro.'' / ''Tengo una casa.''","Indicar quantidade indefinida no plural: ''Hay unos libros sobre la mesa.'' / ''Hay unas flores en el jardín.''"]'::jsonb, '["Usar ''o'' em vez de ''el'': o correto é ''el niño'', nunca ''o niño''.","Usar ''los'' antes de substantivos femininos plurais: o correto é ''las casas'', não ''los casas''.","Esquecer a mudança na formação do plural: ''computador'' vira ''computadores'' (com -es), não ''computadors''.","Confundir a regra geral do gênero: ''la mano'' é feminina, ''el día'' é masculino; observe as exceções."]'::jsonb, '["A regra geral: substantivos terminados em -o são masculinos; terminados em -a, femininos. Exceções existem e devem ser memorizadas.","Para o plural, acrescente -s se a palavra termina em vogal: ''casa'' -> ''casas''. Se termina em consoante, acrescente -es: ''ciudad'' -> ''ciudades''.","Palavras terminadas em -z mudam para -ces no plural: ''lápiz'' -> ''lápices''.","Os artigos sempre concordam com o substantivo em gênero e número."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

