insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-es-a1-c411a140db29', 'es', 'A1', 'Género y número de los sustantivos y artículos', 'Em espanhol, todo substantivo tem gênero (masculino ou feminino) e número (singular ou plural). Os artigos definidos e indefinidos devem concordar com o substantivo em gênero e número. Nesta lição, vamos explorar as regras básicas e as exceções mais comuns para você usar com confiança.', 'Em geral, substantivos terminados em -o são masculinos (el libro, el vaso) e os terminados em -a são femininos (la casa, la puerta). Para o plural, acrescentamos -s às palavras terminadas em vogal (libro → libros) e -es às terminadas em consoante (papel → papeles). Se a palavra termina em -z, trocamos por -ces (lápiz → lápices). Os artigos também mudam: el/los, la/las, un/unos, una/unas.', '["Para identificar objetos e pessoas específicos: el libro, la casa.","Para indicar algo não específico ou genérico: un libro, una casa.","Para falar de mais de um item: los libros, las casas, unos libros, unas casas.","Para manter a concordância de gênero e número entre artigo e substantivo: el niño alto, la niña alta, los niños altos, las niñas altas."]'::jsonb, '["Usar ''la'' com substantivos masculinos: ''la libro'' → ''el libro''.","Esquecer de pluralizar o artigo: ''los casa'' → ''las casas''.","Achar que todas as palavras terminadas em -a são femininas: ''el mapa'', ''el planeta'' são masculinos.","Trocar ''un'' por ''una'' ou vice-versa: ''un mesa'' → ''una mesa''."]'::jsonb, '["Alguns substantivos terminados em -e podem ser masculinos ou femininos: el puente, la mente.","''La mano'' é feminina, mesmo terminando em -o.","''El día'' e ''el mapa'' são masculinos, apesar de terminar em -a.","Abreviaturas como ''foto'' e ''moto'' são femininas: la foto, la moto."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

