insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-es-a1-50823a071808', 'es', 'A1', 'El artículo: género y número', 'Nesta lição, você vai aprender a usar os artigos definidos (el, la, los, las) e indefinidos (un, una, unos, unas) em espanhol. Vamos ver como eles combinam com o gênero (masculino ou feminino) e o número (singular ou plural) dos substantivos. Em português também temos artigos, mas algumas palavras têm gênero diferente. Vamos praticar!', 'Em espanhol, os artigos definidos são: ''el'' para masculino singular (o), ''los'' para masculino plural (os), ''la'' para feminino singular (a), ''las'' para feminino plural (as). Os artigos indefinidos: ''un'' (um), ''unos'' (uns), ''una'' (uma), ''unas'' (umas). Regra geral: substantivos terminados em -o são masculinos e em -a são femininos. Para formar o plural, acrescente -s ou -es: libro -> libros; mujer -> mujeres. O artigo concorda com o substantivo.', '["Use ''el/la'' para falar de algo específico ou já conhecido: ''El libro es rojo.''","Use ''un/una'' para algo não específico ou novo: ''Compro un libro.''","Use ''los/las'' para indicar todos os elementos de um grupo: ''Los niños juegan.''","Use ''unos/unas'' para indicar quantidade indefinida (alguns/algumas): ''Hay unas flores en el jardín.''"]'::jsonb, '["Dizer ''la mano'' está certo, mas não ''el mano''.","Não use ''el problema'' com artigo feminino; ''problema'' é masculino.","Cuidado com ''el día'': apesar de terminar em -a, é masculino.","Não confunda ''una computadora'' (feminino) com ''un ordenador'' (masculino) – ambos significam computador, mas o gênero varia por região."]'::jsonb, '["Memorize o gênero junto com o substantivo: ''el día'', ''la mano'', ''el problema''.","Substantivos que vêm do grego e terminam em -ma são geralmente masculinos: ''el tema'', ''el sistema''.","Em espanhol, ''agua'' é feminino, mas usamos ''el agua'' no singular por causa da sílaba tônica. No plural, dizemos ''las aguas''."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

