insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-es-a1-362403f2f0e4', 'es', 'A1', 'Artículos en español: género y número', 'Nesta lição, você vai aprender os artigos definidos (el, la, los, las) e indefinidos (un, una, unos, unas) em espanhol. Eles devem concordar em gênero (masculino ou feminino) e número (singular ou plural) com o substantivo que acompanham.', 'Tabela de formação: Artigos definidos: el (masculino singular), la (feminino singular), los (masculino plural), las (feminino plural). Artigos indefinidos: un (masculino singular), una (feminino singular), unos (masculino plural), unas (feminino plural).', '["Usa-se o artigo definido para falar de algo específico ou já conhecido: El libro está en la mesa.","Usa-se o artigo indefinido para algo não específico ou mencionado pela primeira vez: Necesito un libro.","O artigo deve concordar com o gênero do substantivo: el niño / la niña.","O artigo deve concordar com o número: los niños / las niñas."]'::jsonb, '["Usar ''la'' com substantivos masculinos: ''la libro'' é incorreto; o certo é ''el libro''.","Esquecer que ''agua'' é feminina, mas usa ''el'' no singular: ''el agua''.","Confundir com o português: ''los'' não é ''os'' em espanhol, embora tenha função parecida."]'::jsonb, '["Substantivos femininos que começam com ''a'' tônica usam ''el'' no singular: el agua, el aula.","No plural, esses substantivos voltam ao artigo feminino: las aguas, las aulas.","Para grupos mistos ou desconhecidos, usa-se o masculino genérico: los estudiantes, unos amigos."]'::jsonb, 0, true)
