insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-es-a1-303188e7e0eb', 'es', 'A1', 'Género y número de sustantivos y artículos', 'Em espanhol, os substantivos têm gênero (masculino ou feminino) e número (singular ou plural). Os artigos (el, la, los, las; un, una, unos, unas) devem concordar com o substantivo em gênero e número.', 'Geralmente, substantivos terminados em -o são masculinos (el libro, los libros) e os terminados em -a são femininos (la casa, las casas). Para formar o plural, adicione -s se a palavra terminar em vogal (libro → libros) e -es se terminar em consoante (pared → paredes). Os artigos definidos são: el/los (masculino singular/plural) e la/las (feminino singular/plural). Os indefinidos são: un/unos (masculino) e una/unas (feminino).', '["Usamos ''el'' com substantivos masculinos singulares: el niño, el coche.","Usamos ''la'' com substantivos femininos singulares: la niña, la mesa.","No plural, usamos ''los'' e ''las'': los niños, las niñas.","Para o singular indeterminado, usamos ''un'' e ''una'': un perro, una flor.","Com substantivos que terminam em -e ou consoante, o gênero é aprendido pelo contexto ou dicionário: el puente, la fuente.","Alguns masculinos terminados em -a e femininos em -o são exceções: el día, la mano."]'::jsonb, '["Dizer ''la problema'' em vez de ''el problema'' (palavras gregas terminadas em -ma são masculinas).","Usar ''un'' com substantivo feminino: ''un casa'' → ''una casa''.","Esquecer o plural do artigo: ''los libro'' → ''los libros''.","Aplicar a regra ''-o'' para todos: ''la mano'' é exceção e é feminina."]'::jsonb, '["Existem substantivos que mudam de significado com o artigo: ''el capital'' (dinheiro) e ''la capital'' (cidade).","Para pessoas e animais, o gênero pode indicar sexo: el actor / la actriz.","No espanhol, também se usa ''el'' antes de ''a'' tônica para evitar cacofonia, mas mantém o gênero feminino: el agua, las aguas."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

