insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-es-a1-5132307871a6', 'es', 'A1', 'Género, número y artículos en español', 'Nesta lição, você vai aprender sobre o gênero (masculino e feminino), o número (singular e plural) e os artigos (definidos e indefinidos) em espanhol. Vamos ver como fazer a concordância correta entre artigos e substantivos, com exemplos práticos.', 'Em espanhol, os artigos definidos são: el (o, masculino singular), la (a, feminino singular), los (os, masculino plural), las (as, feminino plural). Os artigos indefinidos são: un (um, masculino singular), una (uma, feminino singular), unos (uns, masculino plural), unas (umas, feminino plural). O artigo deve concordar com o gênero e o número do substantivo. Em geral, substantivos terminados em -o são masculinos e em -a são femininos. Para formar o plural, adicione -s se a palavra terminar em vogal, e -es se terminar em consoante.', '["Usamos os artigos definidos (el, la, los, las) para falar de algo específico.","Usamos os artigos indefinidos (un, una, unos, unas) para falar de algo não específico ou de um só.","O artigo e o substantivo devem concordar em gênero (masculino/feminino) e número (singular/plural).","Substantivos que terminam em -o geralmente são masculinos (ex.: el libro).","Substantivos que terminam em -a geralmente são femininos (ex.: la casa)."]'::jsonb, '["Confundir o gênero com o português. Por exemplo, ''el mapa'' é masculino em espanhol, assim como ''o mapa'' em português, mas há exceções.","Esquecer a concordância de número: ''las casa'' em vez de ''las casas''.","Usar ''la'' com substantivos masculinos que terminam em -a, como ''el tema''."]'::jsonb, '["Em espanhol, todos os substantivos têm gênero: masculino ou feminino.","Para o plural, adiciona-se -s se terminar em vogal e -es se terminar em consoante.","Algumas palavras são exceções, como ''el día'' (masculino) e ''la mano'' (feminino)."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

