insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-es-a1-adb3bf99377c', 'es', 'A1', 'Artigos, gênero e número em espanhol', 'Em espanhol, os substantivos têm gênero (masculino ou feminino) e número (singular ou plural). Os artigos definidos e indefinidos concordam com o substantivo em gênero e número. Esta lição apresenta as regras principais e alguns casos especiais.', 'Para formar o masculino e o feminino, geralmente usamos as terminações -o e -a: libro (livro) é masculino, mesa (mesa) é feminino. Para formar o plural, adicionamos -s quando a palavra termina em vogal e -es quando termina em consoante: libro -> libros, profesor -> profesores. Os artigos definidos são: el (masculino singular), la (feminino singular), los (masculino plural), las (feminino plural). Os artigos indefinidos são: un, una, unos, unas.', '["Para falar de algo específico: \"El libro está en la mesa.\"","Para falar de algo em geral: \"Los perros son fieles.\"","Para introduzir algo pela primeira vez: \"Tengo un coche.\"","Para falar de profissões sem artigo (mas com verbo ser): \"Soy profesora.\"","Para expressar preferências: \"Me gusta el café.\"","Para indicar hora: \"Son las tres.\""]'::jsonb, '["Confundir \"el\" (artigo) com \"él\" (ele).","Usar \"la\" com substantivos masculinos como \"el problema\", \"el día\".","Esquecer a concordância no plural: \"los libros\" não \"els libros\".","Usar \"un\" antes de substantivo feminino: deve ser \"una mesa\".","Transferir o uso do artigo do português: em espanhol não se usa artigo antes de alguns nomes próprios, mas em certas construções."]'::jsonb, '["Alguns substantivos têm gênero irregular: el mapa, la mano.","Palavras de origem grega terminadas em -ma são masculinas: el tema, el problema.","\"Lo\" é um artigo neutro usado com adjetivos: lo bueno, lo malo.","O plural de \"el\" é \"los\", mas em combinação com \"de\" pode haver contração: del.","Ao aprender, memorize o gênero junto com o substantivo.","Certos substantivos mudam de significado com o artigo: el capital (capital financeiro) vs la capital (capital de um país).","Após \"hay\" usamos geralmente artigo indefinido: \"Hay un libro\".","Para nacionalidades e profissões, não se usa artigo em espanhol com o verbo ser: \"Soy brasileña\" (não \"soy una brasileña\")."]'::jsonb, 0, true)
