insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-es-a1-be3dfd88c5d4', 'es', 'A1', 'Artículos definidos e indefinidos: género y número', 'Em espanhol, assim como no português, os artigos concordam em gênero e número com o substantivo. Nesta lição, você vai aprender a usar os artigos definidos (el, la, los, las) e indefinidos (un, una, unos, unas) corretamente.', 'Definidos: el (masculino singular), la (feminino singular), los (masculino plural), las (feminino plural). Indefinidos: un (masculino singular), una (feminino singular), unos (masculino plural), unas (feminino plural).', '["Use ''el'' antes de substantivos masculinos singulares: el libro.","Use ''la'' antes de substantivos femininos singulares: la mesa.","Use ''los'' antes de substantivos masculinos plurais: los libros.","Use ''las'' antes de substantivos femininos plurais: las mesas.","Use ''un'' para um substantivo masculino indeterminado: un perro.","Use ''una'' para um substantivo feminino indeterminado: una casa.","Use ''unos'' e ''unas'' para plurais indeterminados: unos perros, unas casas."]'::jsonb, '["Trocar o gênero em palavras que mudam em espanhol, como ''el puente'' (a ponte) e ''la leche'' (o leite).","Usar artigo masculino para substantivos femininos terminados em -a: ''la mano'' e não ''el mano''.","Esquecer o plural do artigo: ''los niños'' e não ''los niño''.","Usar ''un'' com substantivos femininos: ''una flor'' e não ''un flor''."]'::jsonb, '["Substantivos terminados em -o geralmente são masculinos: el techo.","Substantivos terminados em -a geralmente são femininos: la silla.","Plural: adicione -s a palavras terminadas em vogal e -es a terminadas em consoante.","Palavras terminadas em -ción e -sión são femininas: la canción, la televisión.","Palavras terminadas em -dad são femininas: la ciudad, la verdad.","Atenção: ''el agua'' é feminino, mas usa-se ''el'' no singular por razão fonética; no plural: ''las aguas''."]'::jsonb, 0, true)
