insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-es-a1-80b96fe60959', 'es', 'A1', 'Gênero, número e artigos em espanhol', 'Em espanhol, assim como em português, os substantivos têm gênero (masculino ou feminino) e número (singular ou plural). Os artigos definidos (el, la, los, las) e indefinidos (un, una, unos, unas) devem concordar em gênero e número com o substantivo. Nesta lição, vamos aprender as regras básicas e algumas exceções importantes para usar os artigos corretamente.', 'Para o singular, geralmente:
- Masculino: termina em -o, usa el/un. Exemplo: el libro, un perro.
- Feminino: termina em -a, usa la/una. Exemplo: la casa, una mesa.
Para o plural:
- Adicione -s se a palavra terminar em vogal: libro → libros, casa → casas.
- Adicione -es se terminar em consoante: ciudad → ciudades, profesor → profesores.
- Os artigos definidos plurais são los (masculino) e las (feminino). Os indefinidos são unos (masculino) e unas (feminino).', '["Para identificar pessoas e animais: el hombre, la mujer, el gato, la gata.","Para falar de objetos e lugares: el libro, la casa, los libros, las casas.","Para expressar quantidade indefinida: un amigo, una amiga, unos amigos, unas amigas.","Palavras terminadas em -ción, -dad, -tad são geralmente femininas: la canción, la ciudad, la libertad.","Palavras terminadas em -o, -or, -aje são geralmente masculinas: el trabajo, el motor, el viaje.","Atenção a exceções: la mano (feminina), el día (masculino), el mapa (masculino)."]'::jsonb, '["Tratar ''agua'' como masculino porque dizemos ''el agua''. Na verdade, é feminina, mas usa-se ''el'' antes de ''a'' tônica para evitar a dupla vogal. Então: ''el agua'' (mas ''las aguas'').","Confundir ''la mano'' como masculino por terminar em -o. É feminino: la mano.","Esquecer que ''día'' é masculino: el día, não ''la día''.","Plural de palavras terminadas em -z: trocar por -ces: la luz → las luces, el pez → los peces.","Usar ''un'' ou ''una'' indevidamente para plural. Para plural indefinido, use ''unos'' ou ''unas''."]'::jsonb, '["O artigo definido neutro ''lo'' é usado com adjetivos para expressar qualidades abstratas: lo bueno, lo malo.","Em espanhol, não se usa artigo antes de profissões em certas frases: ''Soy profesor'', não ''Soy un profesor''.","Com dias da semana e datas, usa-se artigo definido: ''Hoy es lunes'' mas ''El lunes voy a trabajar''.","Antes de nomes próprios, geralmente não se usa artigo: ''María es mi amiga'', não ''La María''."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

