insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-es-a1-11b063a9ebda', 'es', 'A1', 'Género, número y artículos en español', 'Neste tópico, vamos aprender sobre o gênero (masculino/feminino) e o número (singular/plural) dos substantivos em espanhol, e como usar os artigos definidos (el, la, los, las) e indefinidos (un, una, unos, unas) corretamente.', 'Em espanhol, os substantivos têm gênero: geralmente, palavras terminadas em -o são masculinas (el libro, el niño) e palavras terminadas em -a são femininas (la mesa, la niña). Existem exceções, como ''el día'' (masculino) e ''la mano'' (feminino). Para formar o plural, adicionamos -s se a palavra termina em vogal (libro -> libros, casa -> casas) e -es se termina em consoante (reloj -> relojes, ciudad -> ciudades). Os artigos definidos são: el (masculino singular), la (feminino singular), los (masculino plural), las (feminino plural). Os artigos indefinidos são: un (masculino singular), una (feminino singular), unos (masculino plural), unas (feminino plural). Eles devem concordar em gênero e número com o substantivo.', '["Usamos o artigo definido para falar de algo específico ou já conhecido: ''El libro está en la mesa.''","Usamos o artigo indefinido para falar de algo não específico ou mencionado pela primeira vez: ''Hay un libro en la mesa.''","O artigo deve concordar com o gênero e o número do substantivo: ''la niña'' (fem. sing.), ''los niños'' (masc. plur.).","Os artigos indefinidos ''unos'' e ''unas'' significam ''alguns''/''umas'': ''unos libros'', ''unas casas''."]'::jsonb, '["Usar ''la'' com substantivos masculinos que terminam em -a, como ''el problema'' (não ''la problema'').","Usar ''un'' com substantivos femininos: ''una casa'' (não ''un casa'').","Esquecer de pluralizar o artigo: ''los libros'' (não ''el libros'').","Aplicar a regra de plural de forma incorreta: ''relojes'' (não ''relojs'')."]'::jsonb, '["Muitos substantivos que terminam em -e ou consoante podem ser masculinos ou femininos; é preciso aprender com o uso. Exemplo: ''el puente'' (masc.), ''la fuente'' (fem.).","Atenção: ''el agua'' usa ''el'' porque ''agua'' começa com ''a'' tônica, mas é feminino: ''el agua fría''.","Os artigos indefinidos têm sentido de ''um'', ''uma'', ''uns'', ''umas''.","Em espanhol, os adjetivos também concordam em gênero e número com o substantivo: ''casa grande'', ''libro grande''."]'::jsonb, 0, true)
