insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-es-a1-109eb9b68244', 'es', 'A1', 'Los artículos: género y número', 'Nesta aula, você vai aprender como os artigos em espanhol concordam com o gênero (masculino/feminino) e o número (singular/plural) dos substantivos. Como o português tem regras parecidas, o conteúdo será mais fácil!', 'Em espanhol, os artigos definidos são: el (masculino singular), los (masculino plural), la (feminino singular), las (feminino plural). Os artigos indefinidos são: un (masculino singular), unos (masculino plural), una (feminino singular), unas (feminino plural). Use el/un com substantivos masculinos e la/una com femininos. Para o plural, adicione -s ou -es ao substantivo e use o artigo plural correspondente.', '["Use el/los/la/las para falar de algo específico: El libro está en la mesa.","Use un/unos/una/unas para falar de algo não específico: Necesito un lápiz.","Use o artigo plural quando há mais de uma pessoa, animal ou coisa: Las casas son grandes.","Atenção à palavra ''agua'': apesar de ser feminina, usamos ''el agua'' no singular por causa do ''a'' tônico."]'::jsonb, '["Errar o gênero: ''la libro'' em vez de ''el libro''.","Usar artigo masculino plural com substantivo feminino: ''los mesas'' em vez de ''las mesas''.","Esquecer o artigo plural: ''un libro'' para vários livros, em vez de ''unos libros''.","Aplicar a exceção de ''agua'' a todas as palavras que começam com ''a'': ''la amiga'' não vira ''el amiga''."]'::jsonb, '["No espanhol, os substantivos que terminam em -o normalmente são masculinos (el carro), e os que terminam em -a são femininos (la casa).","Há exceções, como ''el día'' (masculino com -a) e ''la mano'' (feminino com -o).","Para formar o plural, acrescente -s se a palavra termina em vogal (libro -> libros) e -es se termina em consoante (papel -> papeles).","Palavras que terminam em -z mudam para -ces no plural: lápiz -> lápices.","A exceção do ''el agua'' ocorre porque ''agua'' começa com ''a'' tônica; mas no plural voltamos ao feminino: las aguas."]'::jsonb, 0, true)
