insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-es-a1-459abf4cdbf0', 'es', 'A1', 'Género y número: sustantivos y artículos', 'Nesta lição, você vai aprender como identificar o gênero (masculino/feminino) e o número (singular/plural) dos substantivos em espanhol, e como usar os artigos definidos e indefinidos corretamente.', 'Em espanhol, os substantivos têm gênero: geralmente terminam em -o para masculino e -a para feminino. Exceções comuns como ''el día'', ''la mano''. Para o plural, adicionamos -s ou -es. Os artigos: el/los, la/las (definidos); un/unos, una/unas (indefinidos). A regra básica: para masculino singular use ''el'' ou ''un''; feminino singular ''la'' ou ''una''; plurais: ''los''/''unos'' para masculino, ''las''/''unas'' para feminino.', '["Para falar de pessoas: el hombre, la mujer, los niños, las niñas.","Para objetos: el libro, la mesa, los cuadernos, las sillas.","Para lugares: el parque, la ciudad, los países, las playas.","Para animais: el perro, la gata, los gatos, las aves."]'::jsonb, '["Usar ''la'' antes de substantivos masculinos como ''el mapa'' (na verdade ''el mapa'', não ''la mapa'').","Esquecer a mudança de artigo no plural: ''el libro'' → ''los libros'', não ''los libro''.","Confundir exceções: ''el día'', ''la mano'', ''el agua'' (mas ''las aguas'')."]'::jsonb, '["Muitos substantivos terminados em -e podem ser masculinos ou femininos: el puente, la calle.","Substantivos terminados em -ción, -sión, -dad, -tad são geralmente femininos: la canción, la ciudad.","Terminados em -aje são geralmente masculinos: el viaje, el mensaje.","No plural, artigos indefinidos ''unos''/''unas'' significam ''alguns/algumas''."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

