insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-es-a1-732c9c35ef0b', 'es', 'A1', 'Gênero e Número dos Substantivos e Artigos', 'Em espanhol, os substantivos têm gênero (masculino ou feminino) e número (singular ou plural). Os artigos definidos (el, la, los, las) e indefinidos (un, una, unos, unas) concordam com o substantivo. Nesta lição, vamos aprender as regras básicas para identificar o gênero e formar o plural.', '1. Substantivos terminados em -o geralmente são masculinos: el libro, el carro.
2. Substantivos terminados em -a geralmente são femininos: la casa, la mesa.
3. Exceções: el día, la mano, el mapa, etc.
4. Para o plural, adiciona-se -s se o substantivo termina em vogal (libro → libros) e -es se termina em consoante (papel → papeles).
5. Artigos definidos: el (masculino singular), los (masculino plural), la (feminino singular), las (feminino plural).
6. Artigos indefinidos: un (masculino singular), una (feminino singular), unos (masculino plural), unas (feminino plural).', '["Usamos artigos definidos para falar de algo específico: ''El libro es interesante.''","Usamos artigos indefinidos para falar de algo não específico: ''Tengo un coche.''","Para falar de quantidade indefinida no plural: ''Unos amigos me visitaron.''","Os artigos definidos também são usados para falar de categorias gerais: ''Me gusta la música.''"]'::jsonb, '["Confundir o gênero: ''la mano'' é feminino, não ''el mano''.","Usar ''una'' com substantivos masculinos: ''una problema'' (errado), ''un problema'' (correto).","Esquecer a concordância de número: ''los libro'' (errado), ''los libros'' (correto).","Aplicar a regra do -a para todos os femininos: ''el día'' é masculino."]'::jsonb, '["Nem sempre a terminação indica gênero: ''la foto'' é feminino, ''el problema'' é masculino.","No plural, o artigo também muda: ''unos'', ''unas'', ''los'', ''las''.","Em espanhol, não usamos artigos antes de profissões em certos contextos, mas em geral usamos."]'::jsonb, 0, true)
