insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-es-a1-19d44e7eff1a', 'es', 'A1', 'Género, número y artículos en español', 'Nesta lição, você vai aprender a identificar o gênero (masculino e feminino) e o número (singular e plural) de substantivos em espanhol, além de usar corretamente os artigos definidos e indefinidos. Isso é essencial para formar frases simples e corretas.', 'Em espanhol, os artigos definidos são: el (masculino singular), la (feminino singular), los (masculino plural) e las (feminino plural). Os artigos indefinidos são: un (masculino singular), una (feminino singular), unos (masculino plural) e unas (feminino plural). Regra geral: substantivos terminados em -o são masculinos (el libro), e terminados em -a são femininos (la mesa). Para formar o plural, adiciona-se -s ou -es: libro → libros, mujer → mujeres. O artigo também deve concordar em gênero e número.', '["Para falar de pessoas e animais: el hombre, la mujer, el gato, la gata.","Para falar de objetos e coisas: el libro, la mesa, los cuadernos, las sillas.","Para indicar algo específico ou já conhecido: el libro que compré ayer.","Para indicar algo não específico ou mencionado pela primeira vez: un libro, una casa.","Para expressar generalizações: Los perros son fieles (Os cães são fiéis)."]'::jsonb, '["Usar ''la'' antes de palavras femininas que começam com ''a'' tônica: o correto é ''el agua'' e não ''la agua''.","Confundir ''un'' e ''una'': ''un casa'' está errado; o correto é ''una casa''.","Esquecer a concordância no plural: ''los libro'' em vez de ''los libros''.","Usar artigo masculino para substantivos femininos irregulares: ''la mano'' (não ''el mano''), ''la foto'' (não ''el foto'')."]'::jsonb, '["Em espanhol, os adjetivos também concordam em gênero e número com o substantivo: casa blanca, casas blancas.","Alguns substantivos têm gênero irregular: el día (masculino), la mano (feminino).","Ao aprender um substantivo novo, memorize-o com seu artigo para facilitar a concordância.","Em espanhol, não se usa artigo antes de países e idiomas em muitos contextos, mas isso será visto em níveis posteriores."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

