insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-es-a1-0f2fa3067eeb', 'es', 'A1', 'Los artículos, el género y el número en español', 'Nesta lição, você vai entender como funcionam os artigos definidos e indefinidos em espanhol. Você vai aprender a identificar o gênero (masculino e feminino) e o número (singular e plural) dos substantivos, para escolher o artigo correto.', 'Em espanhol, os artigos concordam em gênero e número com o substantivo. Veja as formas:

**Artigos definidos:**
- el (masculino singular) – el libro
- la (feminino singular) – la casa
- los (masculino plural) – los libros
- las (feminino plural) – las casas

**Artigos indefinidos:**
- un (masculino singular) – un libro
- una (feminino singular) – una casa
- unos (masculino plural) – unos libros
- unas (feminino plural) – unas casas

**Formação do plural:**
- Se termina em vogal, acrescente -s: libro → libros; casa → casas.
- Se termina em consoante, acrescente -es: mujer → mujeres; color → colores.

**Dica de gênero:**
- Substantivos terminados em -o geralmente são masculinos: el perro, el zapato.
- Substantivos terminados em -a geralmente são femininos: la mesa, la ventana.
- Há exceções: el día, la mano, el mapa, la foto (de fotografía).', '["Use artigos definidos para falar de algo específico ou já conhecido: el libro que compré (o livro que comprei).","Use artigos indefinidos para falar de algo não específico ou mencionado pela primeira vez: un libro (um livro qualquer).","Para dizer a profissão, geralmente se usa artigo indefinido: Soy un profesor (mas também pode omitir em alguns contextos).","Use artigos definidos antes de substantivos que representam toda a categoria: Los perros son fieles (Os cães são fiéis).","Para indicar posse de forma genérica, usa-se artigo definido: Me duele la cabeza (literalmente: dói-me a cabeça)."]'::jsonb, '["Confundir o gênero de substantivos que terminam em -a mas são masculinos: el problema, el sistema, el tema. Nunca diga ''la problema''.","Esquecer que ''agua'' é feminino, mas usa ''el'' no singular por causa do ''a'' tônico: el agua, las aguas. Portanto, ''el agua fría'' (água fria) - observe que o adjetivo fica no feminino.","Usar ''un'' antes de substantivos femininos: uma casa → una casa, não ''un casa''.","Formar o plural de palavras terminadas em consoante sem acrescentar -es: la mujer → las mujeres (não ''las mujers'').","Usar ''los'' para substantivos femininos plurais: las mesas (não ''los mesas'')."]'::jsonb, '["O artigo ''el'' também pode ser usado antes de femininos que começam com ''a'' tônica, como ''el agua'', ''el aula'', mas no plural volta a usar ''las'': las aguas, las aulas.","Os artigos indefinidos no plural (unos, unas) significam ''uns, umas'' ou ''alguns, algumas''.","Em espanhol, não se usa artigo antes de países, exceto alguns casos: España é sem artigo, mas El Salvador, La India (opcional).","Para perguntar ''o que é isto?'' você pode usar ''¿Qué es esto?'' sem artigo.","Quando falamos de horas, usamos artigo definido feminino: Es la una (é uma hora), Son las dos (são duas horas).","Note que ''el'' é usado antes de ''día'' (masculino) e ''la'' antes de ''noche'' (feminino)."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

