insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-es-a1-8ecbe40ab87f', 'es', 'A1', 'Gênero, número e artigos em espanhol', 'Nesta lição, você vai aprender como os substantivos em espanhol têm gênero (masculino ou feminino) e número (singular ou plural). Os artigos definidos e indefinidos devem concordar com o substantivo. Para quem fala português, muitas regras são parecidas, mas existem diferenças importantes.', 'Os artigos definidos são: el (masculino singular), los (masculino plural), la (feminino singular) e las (feminino plural). Os artigos indefinidos são: un (masculino singular), unos (masculino plural), una (feminino singular) e unas (feminino plural). Para formar o plural: se o substantivo termina em vogal, adicione -s (libro → libros). Se termina em consoante, adicione -es (mujer → mujeres).', '["Usamos el/la para falar de algo específico: El libro está en la mesa.","Usamos un/una para apresentar algo novo ou não específico: Tengo un perro.","Usamos los/las para um grupo específico: Las mujeres hablan español.","Usamos unos/unas para um grupo indefinido: Unos amigos me visitaron."]'::jsonb, '["Não diga ''la mapa''; o correto é ''el mapa'', porque ''mapa'' é masculino.","Não confunda ''el día'' com ''la día''; ''día'' é masculino.","Não esqueça o artigo no plural: ''los libros'' e não ''los libro''.","Não use artigo masculino com palavras terminadas em -ción; ex.: ''la canción''."]'::jsonb, '["Substantivos terminados em -o geralmente são masculinos: el libro, el carro.","Substantivos terminados em -a geralmente são femininos: la casa, la mesa.","Palavras terminadas em -ción, -sión, -dad, -tud são femininas: la ciudad, la televisión.","Palavras terminadas em -e podem ser masculinas ou femininas: el puente, la calle."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

