insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-es-a1-810e4732d1ca', 'es', 'A1', 'Artículos y concordancia de género y número', 'Em espanhol, os substantivos têm gênero (masculino ou feminino) e número (singular ou plural). Os artigos definidos e indefinidos devem concordar com o substantivo em gênero e número. Nesta lição, você vai aprender as regras básicas e praticar com exercícios.', 'A maioria dos substantivos masculinos termina em -o (ex.: libro) e femininos em -a (ex.: mesa). O plural é formado acrescentando-se -s se a palavra termina em vogal, ou -es se termina em consoante. Artigos definidos: el (masculino singular), la (feminino singular), los (masculino plural), las (feminino plural). Artigos indefinidos: un, una, unos, unas. Exemplos: el libro → los libros; la mesa → las mesas; un libro → unos libros; una mesa → unas mesas.', '["Use os artigos definidos (el, la, los, las) para falar de coisas específicas ou conhecidas.","Use os artigos indefinidos (un, una, unos, unas) para falar de coisas não específicas ou desconhecidas.","Use o artigo masculino com substantivos masculinos e o artigo feminino com substantivos femininos.","Use o artigo singular para um item e o plural para mais de um."]'::jsonb, '["Confundir o gênero porque muitas palavras em português têm gênero diferente do espanhol (ex.: ''el puente'' vs. ''a ponte'').","Usar ''el'' ou ''los'' com substantivos femininos terminados em -a.","Omitir o artigo quando em português ele é desnecessário, mas em espanhol é obrigatório.","Esquecer de pluralizar o artigo junto com o substantivo."]'::jsonb, '["Muitos substantivos terminados em -e podem ser masculinos ou femininos; consulte um dicionário.","Os artigos definidos são usados com os dias da semana (ex.: el lunes).","Unos/unas também podem significar ''alguns'' ou ''aproximadamente'' (ex.: unos diez minutos).","Quando um substantivo feminino singular começa com ''a'' ou ''ha'' tônico, usamos ''el'' por eufonia (ex.: el agua), mas mantemos o adjetivo feminino (ex.: el agua fría)."]'::jsonb, 0, true)
