insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-es-a1-4a0cd164ebec', 'es', 'A1', 'Gênero e Número: Substantivos e Artigos em Espanhol', 'Em espanhol, assim como em português, os substantivos têm gênero (masculino ou feminino) e número (singular ou plural). Os artigos definidos e indefinidos concordam com o substantivo em gênero e número. Nesta lição, você vai aprender as regras básicas e algumas exceções importantes.', 'Em espanhol, os substantivos têm gênero (masculino ou feminino) e número (singular ou plural). Os artigos concordam com o substantivo.

**Masculino** geralmente termina em **-o**: el libro, el chico. Também terminam em **-e** ou consoante: el tren, el papel.

**Feminino** geralmente termina em **-a**: la casa, la chica. Também terminam em **-ción, -sión, -dad, -tad**: la canción, la ciudad.

**Exceções comuns**: el mapa, el día, la mano, la foto, la moto.

**Plural**: vogal + **-s** (el libro → los libros); consoante + **-es** (el papel → los papeles). Cuidado com a mudança de acento: la canción → las canciones.

**Artigos definidos**: el, la, los, las. **Indefinidos**: un, una, unos, unas.', '["Para identificar pessoas e objetos: ''El profesor es simpático.''","Para falar de coisas em geral: ''Los perros son leales.''","Para indicar quantidade indefinida: ''Necesito un bolígrafo.''","Para falar de nacionalidades e profissões: ''Ella es una abogada.''"]'::jsonb, '["Usar ''lo'' como artigo definido masculino (em espanhol não é artigo, é pronome).","Esquecer que palavras como ''mano'' são femininas: ''la mano''.","Pluralizar palavras com consoante apenas com -s: ''papels'' em vez de ''papeles''.","Usar ''um'' em vez de ''un'' para masculino (influência do português)."]'::jsonb, '["Em espanhol, o artigo definido feminino é ''la'', mas antes de ''a'' tônica usa-se ''el'': ''el agua'' (mas feminino).","Alguns substantivos mudam de significado com o gênero: ''el capital'' (dinheiro) vs ''la capital'' (cidade).","Os indefinidos ''unos'' e ''unas'' também existem, mas são menos usados que no português."]'::jsonb, 0, true)
