insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-es-a1-e1f82e54a730', 'es', 'A1', 'Gênero e número de substantivos e artigos em espanhol', 'Em espanhol, os substantivos têm gênero (masculino ou feminino) e número (singular ou plural). Os artigos definidos e indefinidos variam para concordar com o substantivo. Nesta lição, você vai aprender as formas básicas dos artigos e as principais regras para identificar e formar o gênero e o número dos substantivos.', 'Em geral, substantivos terminados em -o são masculinos e em -a são femininos. Para o plural, adicione -s se a palavra termina em vogal e -es se termina em consoante. Veja os artigos: definidos: el (masc. sing.), los (masc. plur.), la (fem. sing.), las (fem. plur.); indefinidos: un (masc. sing.), unos (masc. plur.), una (fem. sing.), unas (fem. plur.).', '["Use el/un antes de substantivo masculino singular: el libro, un libro.","Use la/una antes de substantivo feminino singular: la casa, una casa.","Use los/unos antes de substantivo masculino plural: los libros, unos libros.","Use las/unas antes de substantivo feminino plural: las casas, unas casas.","Substantivos terminados em -o geralmente são masculinos: el carro, el teléfono.","Substantivos terminados em -a geralmente são femininos: la mesa, la puerta.","Para formar o plural, adicione -s a palavras terminadas em vogal (casa → casas) e -es a palavras terminadas em consoante (profesor → profesores).","Alguns substantivos terminados em -e são masculinos (el coche) e outros femininos (la noche); é necessário memorizar com o artigo."]'::jsonb, '["Não use ''o'' ou ''a'' do português; em espanhol use ''el'' ou ''la''. Ex.: ''el libro'', não ''o libro''.","Não esqueça a concordância de gênero e número: diga ''las casas'', não ''las casa''.","Não use ''un'' com substantivo feminino: diga ''una mujer'', não ''un mujer''.","Não forme o plural de consoantes apenas com ''s'': diga ''profesores'', não ''profesors''.","Não troque ''los'' por ''os'': diga ''los niños'', não ''os niños''."]'::jsonb, '["Em espanhol, os artigos definidos ''el/la/los/las'' equivalem a ''o/a/os/as'' do português.","Os artigos indefinidos ''un/una/unos/unas'' equivalem a ''um/uma/uns/umas''.","Existem diferenças de gênero em relação ao português: ''la mano'' (a mão) é feminino, enquanto ''el día'' (o dia) é masculino.","O artigo ''el'' é usado antes de substantivos femininos que começam com ''a'' tônica, como ''el agua'', ''el área'', mas isso é mais avançado.","Muitas palavras de origem grega terminadas em ''-ma'' são masculinas, como ''el problema'', ''el tema''."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

