insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-es-a1-b20f74f9d111', 'es', 'A1', 'Gênero, número e artigos em espanhol', 'Em espanhol, os substantivos têm gênero (masculino ou feminino) e número (singular ou plural). Os artigos devem concordar em gênero e número com o substantivo. Para brasileiros, a lógica é parecida com a do português, mas há diferenças importantes que precisam ser observadas.', 'Regras de gênero: geralmente, substantivos terminados em -o são masculinos (el libro) e terminados em -a são femininos (la mesa). Exceções comuns devem ser memorizadas (el mapa, la mano). Plurais: se a palavra termina em vogal, acrescenta-se -s (libro → libros); se termina em consoante, acrescenta-se -es (ciudad → ciudades); se termina em -z, troca-se por -ces (lápiz → lápices). Artigos definidos: el/los (masculino singular/plural), la/las (feminino singular/plural). Artigos indefinidos: un/unos (masculino singular/plural), una/unas (feminino singular/plural).', '["Identificar o gênero dos substantivos para escolher o artigo correto.","Usar artigos definidos (el, la, los, las) para falar de algo específico: El libro es mío.","Usar artigos indefinidos (un, una, unos, unas) para falar de algo não específico: Necesito un lápiz.","Formar o plural de substantivos e artigos: un libro → unos libros.","Reconhecer exceções e casos especiais de gênero e número."]'::jsonb, '["Confundir o gênero com o português: el puente (masculino) vs. a ponte (feminino).","Usar ''la'' antes de substantivos femininos que começam com ''a'' tônica: dizemos ''el agua'', não ''la agua''.","Esquecer de pluralizar o artigo junto com o substantivo: ''el libros'' é incorreto; o correto é ''los libros''.","Aplicar regras do português, como ''a gente'' para ''nós'', que não existe em espanhol."]'::jsonb, '["Em espanhol, o artigo neutro ''lo'' é usado para transformar adjetivos em substantivos: lo bueno (o que é bom).","''El'' é usado antes de substantivos femininos que começam com ''a'' tônica para evitar cacofonia: el agua, el águila.","Os artigos indefinidos ''unos'' e ''unas'' significam ''alguns'' ou ''uns''.","Substantivos terminados em ''-ista'' podem ser masculinos ou femininos: el/la turista.","Aprender as exceções mais comuns é essencial para evitar erros: el día, la mano, el mapa, el problema."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

