insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-es-a1-82555b0370de', 'es', 'A1', 'Artículos, género y número', 'Em espanhol, os artigos concordam em gênero (masculino/feminino) e número (singular/plural) com o substantivo. Nesta lição, você vai aprender a usar os artigos definidos (el, la, los, las) e indefinidos (un, una, unos, unas) corretamente.', 'Para formar o plural, geralmente adiciona-se -s a palavras terminadas em vogal e -es a palavras terminadas em consoante. Exemplos: libro -> libros, mujer -> mujeres. Os artigos também mudam: el -> los, la -> las, un -> unos, una -> unas. Atenção a palavras que terminam em -e ou consoante: seu gênero precisa ser memorizado.', '["Usar artigo definido para falar de algo específico: ''El libro es nuevo.''","Usar artigo indefinido para algo não específico: ''Un libro está en la mesa.''","Concordância de gênero: substantivos em -o geralmente masculino, em -a feminino.","Concordância de número: singular/plural no artigo e substantivo.","Artigos contraídos ''del'' (de + el) e ''al'' (a + el)."]'::jsonb, '["Usar ''la'' com substantivos masculinos: ''la teléfono'' (errado) -> ''el teléfono''.","Esquecer o plural no artigo: ''los libro'' (errado) -> ''los libros''.","Usar ''el'' com ''agua'' ou ''águila'' apesar de serem femininos: ''el agua'' é correto, mas o artigo plural é ''las aguas''.","Trocar ''unos'' por ''un'' no plural: ''unos libros'' não ''un libros''."]'::jsonb, '["Alguns substantivos têm gênero irregular: el día, la mano, el mapa.","Substantivos terminados em -ista podem ser masculino ou feminino: el artista, la artista.","Palavras de origem grega terminadas em -ma são masculinas: el tema, el problema.","Em espanhol, ao contrário do português, ''la'' é usada antes de ''a'' tônica para evitar cacofonia: el agua, el águila.","O plural de palavras terminadas em -z troca por -ces: lápiz -> lápices."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

