insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-es-a1-e2ed63157e05', 'es', 'A1', 'Los artículos: género y número', 'Em espanhol, os artigos definidos e indefinidos concordam em gênero (masculino/feminino) e número (singular/plural) com o substantivo. O artigo definido é: el (masculino singular), la (feminino singular), los (masculino plural), las (feminino plural). O artigo indefinido é: un (masculino singular), una (feminino singular), unos (masculino plural), unas (feminino plural).', 'Para formar o plural, acrescentamos -s ou -es ao substantivo e usamos los/las/unos/unas. Exemplos: el libro -> los libros; la casa -> las casas; un amigo -> unos amigos; una mujer -> unas mujeres. A escolha do artigo depende do gênero e do número do substantivo.', '["Usamos el/los com substantivos masculinos: el niño, los niños.","Usamos la/las com substantivos femininos: la niña, las niñas.","Usamos un/unos para algo indefinido no masculino: un libro, unos libros.","Usamos una/unas para algo indefinido no feminino: una mesa, unas mesas."]'::jsonb, '["Não diga ''la problema'' – ''problema'' é masculino: el problema.","Não diga ''un casa'' – ''casa'' é feminino: una casa.","Esquecer o plural no artigo: ''los libro'' está errado; o correto é ''los libros''.","Confundir ''uno'' com ''un'': ''uno'' é pronome, não artigo. Antes de substantivo usamos ''un''."]'::jsonb, '["Alguns substantivos terminados em -a são masculinos (el día, el mapa).","Alguns terminados em -o são femininos (la mano, la foto).","No singular, diante de palavra feminina que começa com ''a'' tônica, usamos ''el'' (el agua), mas no plural usamos ''las'' (las aguas).","Isso não muda o gênero: ''agua'' continua feminino."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

