insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-es-a1-91096b407ee4', 'es', 'A1', 'Gênero, número e artigos em espanhol', 'Nesta lição, você vai aprender como os substantivos em espanhol têm gênero (masculino/feminino) e número (singular/plural), e como os artigos definidos e indefinidos concordam com eles. Isso é essencial para formar frases corretas.', 'Em espanhol, a maioria dos substantivos terminados em -o são masculinos, e os terminados em -a são femininos. Para formar o plural, adicionamos -s a palavras terminadas em vogal e -es a palavras terminadas em consoante. Os artigos definidos são: el (masculino singular), la (feminino singular), los (masculino plural), las (feminino plural). Os artigos indefinidos são: un (masculino singular), una (feminino singular), unos (masculino plural), unas (feminino plural).', '["Para identificar o gênero de um substantivo e usar o artigo correto: ''el libro'' (o livro), ''la casa'' (a casa).","Para falar de algo específico ou genérico: ''Los perros son fieles'' (Os cães são fiéis).","Para indicar quantidade indefinida: ''un cuaderno'' (um caderno), ''unas flores'' (umas flores)."]'::jsonb, '["Usar ''el'' com palavras femininas que começam com ''a'' tônica, como ''el agua'' (mas na verdade é ''el agua'' mas o adjetivo é feminino: ''el agua fría''). Cuidado com essa exceção.","Esquecer de pluralizar o artigo junto com o substantivo: ''los libros'' e não ''los libro''.","Confundir ''un'' e ''una'': ''una mesa'' (uma mesa) e não ''un mesa''."]'::jsonb, '["Para brasileiros: em português usamos ''o'' e ''a'', mas em espanhol ''el'' e ''la''. Preste atenção ao gênero, pois pode ser diferente do português, como ''la mano'' (a mão) e ''el mapa'' (o mapa).","Existem exceções: ''el día'' (dia) é masculino, ''la foto'' (foto) é feminino (abreviação de fotografía).","No plural, nunca use ''los'' com substantivo feminino plural: ''las casas'' e não ''los casas''."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

