insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-es-a1-c411b9dc0a82', 'es', 'A1', 'Artículos definidos e indefinidos: género y número', 'Em espanhol, os artigos definidos (el, la, los, las) e indefinidos (un, una, unos, unas) mudam de forma conforme ao gênero (masculino/feminino) e ao número (singular/plural) do substantivo. Em geral, substantivos terminados em -o são masculinos e em -a são femininos. O artigo deve concordar com o substantivo.', 'Tabela dos artigos: Definidos: el (masculino singular), la (feminino singular), los (masculino plural), las (feminino plural). Indefinidos: un (masculino singular), una (feminino singular), unos (masculino plural), unas (feminino plural). Exemplos: el libro, la casa, los libros, las casas; un libro, una casa, unos libros, unas casas.', '["Usamos ''el'' e ''los'' com substantivos masculinos. Exemplos: ''el niño'', ''los niños''.","Usamos ''la'' e ''las'' com substantivos femininos. Exemplos: ''la niña'', ''las niñas''.","Usamos ''un'' e ''unos'' para indefinidos masculinos: ''un perro'', ''unos perros''.","Usamos ''una'' e ''unas'' para indefinidos femininos: ''una mesa'', ''unas mesas''."]'::jsonb, '["Dizer ''o libro'' em vez de ''el libro'', por influência do português.","Achar que todas as palavras terminadas em -o são masculinas, mas ''la mano'' é feminina.","Esquecer que ''un'' se torna ''uno'' sozinho, mas antes de substantivo é ''un''.","Usar ''el'' antes de palavra feminina plural, como ''el niñas'' em vez de ''las niñas''."]'::jsonb, '["Algumas palavras femininas com ''a'' tônica usam ''el'' no singular: ''el agua'', ''el águila'', mas no plural: ''las aguas''.","Em espanhol, usamos artigo definido com dias da semana: ''el lunes'', ''el martes''.","Para dizer profissões sem artigo: ''Soy profesor'', ''Ella es médico''."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

