insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-es-a1-57cf4f03910c', 'es', 'A1', 'Gênero, número e artigos: o básico em espanhol', 'Nesta lição, você vai aprender como usar os artigos definidos e indefinidos em espanhol, e como concordar com o gênero (masculino/feminino) e o número (singular/plural) dos substantivos.', 'Em espanhol, os substantivos têm gênero. Geralmente, palavras que terminam em ''-o'' são masculinas, e em ''-a'' são femininas. Para o plural, adicionamos ''-s'' a palavras que terminam em vogal e ''-es'' a palavras que terminam em consoante. Os artigos definidos são: el, la, los, las. Os indefinidos são: un, una, unos, unas.', '["Usamos ''el'' e ''la'' (definidos) para falar de algo específico ou já conhecido.","Usamos ''un'' e ''una'' (indefinidos) para apresentar algo não específico.","Os artigos devem concordar em gênero (masculino/feminino) e número (singular/plural) com o substantivo.","No plural, usamos ''los'' e ''las'' para definidos, e ''unos'' e ''unas'' para indefinidos."]'::jsonb, '["Não confunda com o português: em espanhol, ''la'' é para feminino singular, e ''el'' para masculino singular.","Lembre que ''las'' é o plural de ''la'', e ''los'' é o plural de ''el''. Não use ''los'' para feminino.","Alguns estudantes esquecem de usar ''un'' para masculino e ''una'' para feminino, usando ''un'' para todos.","Não use ''lo'' como artigo definido antes de substantivos; ''lo'' é usado apenas com adjetivos ou advérbios."]'::jsonb, '["Alguns substantivos femininos que começam com ''a'' tônica usam ''el'' no singular: ''el agua'', ''el águila'', mas no plural: ''las aguas''.","As cores, nacionalidades e muitas profissões mudam de forma para feminino: ''rojo'' → ''roja'', ''médico'' → ''médica''.","Palavras de origem grega terminadas em ''-ma'' geralmente são masculinas: ''el problema'', ''el tema''.","Os dias da semana são masculinos: ''el lunes'', ''el sábado''. Os meses também: ''el mes de enero''."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

