insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-es-a1-1fcd920760c6', 'es', 'A1', 'Género y número: sustantivos y artículos', 'Em espanhol, os substantivos têm gênero (masculino ou feminino) e número (singular ou plural). Os artigos definidos e indefinidos concordam com o substantivo em gênero e número. Nesta lição, você vai aprender as regras básicas para usar corretamente el, la, los, las, un, una, unos, unas.', 'Gênero: Substantivos masculinos geralmente terminam em -o (el libro) e femininos em -a (la casa). Número: Para formar o plural, adiciona-se -s se o substantivo termina em vogal (libro -> libros) e -es se termina em consoante (ciudad -> ciudades). Artigos: Definidos: el (masculino singular), los (masculino plural), la (feminino singular), las (feminino plural). Indefinidos: un (masculino singular), unos (masculino plural), una (feminino singular), unas (feminino plural).', '["Usamos artigos definidos (el, la, los, las) para falar de algo específico: el libro de María, la casa blanca.","Usamos artigos indefinidos (un, una, unos, unas) para falar de algo não específico: un libro (um livro qualquer), una casa (uma casa qualquer).","Para falar de pessoas e animais: el hombre, la mujer, el gato, la gata.","Para falar de objetos e lugares: la mesa, el parque, los árboles."]'::jsonb, '["Errar o gênero: ''la libro'' em vez de ''el libro''.","Errar o número: ''dos libro'' em vez de ''dos libros''.","Usar ''un'' com substantivo feminino: ''un casa'' em vez de ''una casa''.","Esquecer que alguns substantivos terminados em -a são masculinos: ''el mapa'', ''el día''.","Esquecer que alguns substantivos terminados em -o são femininos: ''la mano'', ''la foto''."]'::jsonb, '["Para grupos mistos, o espanhol usa o masculino: los niños (meninos e meninas).","O artigo indefinido no plural (unos, unas) significa ''alguns'' ou ''umas''.","Em espanhol, as palavras ''agua'', ''hada'', ''águila'' usam ''el'' no singular para evitar hiato: el agua, pero las aguas. Este é um detalhe importante, mas talvez avançado para A1.","Quando o substantivo é feminino e começa com ''a'' tônica, usa-se ''el'' no singular: el agua, el águila, pero las aguas, las águilas."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

