insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-es-a1-58d908ce7906', 'es', 'A1', 'Gênero, número e artigos em espanhol', 'Nesta lição, você vai aprender como os substantivos em espanhol têm gênero (masculino ou feminino) e número (singular ou plural). Também vai estudar os artigos definidos (el, la, los, las) e indefinidos (un, una, unos, unas) e como eles concordam com os substantivos. Vamos começar com regras simples e alguns exemplos úteis para o dia a dia.', '1) Gênero: substantivos terminados em -o são geralmente masculinos (ex.: libro, carro). Terminados em -a são geralmente femininos (ex.: casa, mesa). Exceções comuns: el día (masculino), la mano (feminino), el problema (masculino). 2) Número: para formar o plural, acrescente -s se a palavra termina em vogal (libro → libros) e -es se termina em consoante (papel → papeles). 3) Artigos: definidos → el/la (singular), los/las (plural); indefinidos → un/una (singular), unos/unas (plural).', '["Usamos artigos definidos para algo específico ou já conhecido: El libro está en la mesa.","Usamos artigos indefinidos para algo não específico: Necesito un libro.","Para um grupo misto de homens e mulheres, usamos o masculino plural: Los amigos.","Alguns substantivos têm gênero diferente do português: la sal (o sal), el puente (a ponte).","No plural, o artigo também deve estar no plural: Las casas son grandes."]'::jsonb, '["Não confundir ''el'' com o português ''o''. Dizemos ''el libro'', nunca ''o libro''.","Não usar ''la'' com substantivos masculinos como ''problema''. O correto é ''el problema''.","Esquecer a concordância: ''un casa'' é errado; o certo é ''una casa''.","Usar ''los'' para feminino plural: ''los flores'' é errado; o certo é ''las flores''.","Pensar que todo substantivo terminado em -a é feminino. Ex.: ''el mapa'' (masculino)."]'::jsonb, '["Palavras de origem grega terminadas em -ma, -ta, -pa geralmente são masculinas: el tema, el mapa, el planeta.","Em espanhol, o artigo definido feminino ''la'' vira ''el'' antes de palavras femininas com ''a'' tônica: el agua, el águila (mas isso é tema mais avançado).","Cores concordam com o substantivo: el coche rojo, la casa roja.","Os artigos indefinidos também têm plural: unos, unas.","Profissões podem mudar de artigo: el médico, la médica.","Não usamos artigo antes de alguns países, mas isso é uma exceção.","Para perguntar ''o que é isto?'', usamos ''¿Qué es esto?'' e a resposta geralmente inclui o artigo."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

