insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-es-a1-ff25fc6a47f0', 'es', 'A1', 'Artículos: gênero e número', 'Em espanhol, os artigos definidos e indefinidos concordam em gênero (masculino/feminino) e número (singular/plural) com o substantivo. Isso é semelhante ao português, mas há diferenças importantes. Nesta lição, você vai aprender as formas dos artigos e como usá-los corretamente.', 'Os artigos definidos são: el (masculino singular), los (masculino plural), la (feminino singular) e las (feminino plural). Os indefinidos são: un (masculino singular), unos (masculino plural), una (feminino singular) e unas (feminino plural). Em geral, substantivos terminados em -o são masculinos e em -a são femininos, mas há exceções (ex.: el día, la mano, el mapa).', '["Use ''el'' ou ''un'' com substantivos masculinos singulares: el libro, un perro.","Use ''la'' ou ''una'' com substantivos femininos singulares: la casa, una mesa.","Use ''los'' ou ''unos'' com substantivos masculinos plurais: los libros, unos perros.","Use ''las'' ou ''unas'' com substantivos femininos plurais: las casas, unas mesas."]'::jsonb, '["Não confundir o gênero com o português. Por exemplo, ''el mapa'' é masculino em espanhol, enquanto ''o mapa'' em português também é masculino, mas cuidado com palavras como ''la foto'' (foto é feminino em espanhol, apesar de terminar em -o).","Não usar ''un'' diante de substantivo feminino. Escreva ''una casa'', não ''un casa''.","Não esquecer a concordância de número: ''los libros'' e não ''los libro''.","Em espanhol, não se usa artigo definido antes de nomes próprios de pessoas (ex.: ''María'', não ''la María''), exceto em alguns casos coloquiais."]'::jsonb, '["Quando uma palavra feminina começa com ''a'' tônica (ex.: agua), usa-se ''el'' no singular: ''el agua''. Mas no plural: ''las aguas''.","As contrações ''al'' (a + el) e ''del'' (de + el) são obrigatórias em espanhol.","Muitas palavras que terminam em -ción, -sión, -dad, -tad são femininas: la canción, la ciudad."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

