insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-es-a1-31004e0b6c00', 'es', 'A1', 'Gênero e número: artigos definidos e indefinidos', 'Em espanhol, os substantivos têm gênero (masculino ou feminino) e número (singular ou plural). Os artigos definidos (el, la, los, las) e indefinidos (un, una, unos, unas) concordam com o substantivo em gênero e número. Nesta aula, você vai aprender as regras básicas para usar esses artigos corretamente.', 'No singular: masculino usa ''el'' (definido) e ''un'' (indefinido); feminino usa ''la'' e ''una''. No plural: masculino usa ''los'' e ''unos''; feminino usa ''las'' e ''unas''. Em geral, substantivos terminados em ''-o'' são masculinos e terminados em ''-a'' são femininos. Para formar o plural, acrescenta-se ''-s'' se a palavra termina em vogal e ''-es'' se termina em consoante.', '["Para referir-se a algo específico ou já conhecido, usamos os artigos definidos. Exemplo: El libro es interesante.","Para referir-se a algo não específico ou mencionado pela primeira vez, usamos os artigos indefinidos. Exemplo: Un libro está en la mesa.","Para indicar todos os elementos de um grupo, usamos os artigos definidos no plural. Exemplo: Los perros son fieles.","Para indicar quantidade indeterminada, usamos os artigos indefinidos no plural. Exemplo: Unos amigos vienen hoy.","Com os dias da semana, em espanhol, costuma-se usar o artigo definido. Exemplo: El lunes voy al trabajo.","Para palavras femininas que começam com ''a'' tônica, usamos ''el'' no singular, mas ''las'' no plural. Exemplo: El agua está fría; Las aguas están limpias."]'::jsonb, '["Usar ''la'' antes de substantivos femininos que começam com ''a'' tônica. O correto é ''el'' (ex.: el agua, el águila).","Esquecer a concordância de número: ''los libro'' em vez de ''los libros''.","Usar ''un'' com substantivos femininos: ''un casa'' em vez de ''una casa''.","Confundir ''el'' (artigo) com ''él'' (pronome pessoal).","Achar que todos os substantivos terminados em ''-o'' são masculinos. Exceção: ''la mano'' (a mão) é feminina."]'::jsonb, '["Não existe artigo neutro em espanhol.","Alguns substantivos têm gênero diferente do português: ''la leche'' (o leite), ''el puente'' (a ponte), ''el árbol'' (a árvore).","Os artigos indefinidos ''unos'' e ''unas'' podem significar ''alguns'' ou ''umas''."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

