insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-fr-a1-2a4e76bd7d9d', 'fr', 'A1', 'Gênero e número dos substantivos e artigos', 'Nesta lição, você vai aprender como identificar o gênero (masculino/feminino) e o número (singular/plural) dos substantivos em francês, e como usar os artigos definidos e indefinidos corretamente.', 'Em francês, os substantivos têm gênero, e os artigos concordam com eles. O artigo indefinido singular é ''un'' para masculino e ''une'' para feminino. O artigo definido é ''le'' para masculino singular, ''la'' para feminino singular, ''l'''' antes de vogal, e ''les'' no plural. O plural dos substantivos geralmente se forma acrescentando um ''s'' (que não é pronunciado na maioria dos casos). O artigo indefinido plural é ''des''.', '[{"case":"Para indicar uma pessoa ou coisa específica, use os artigos definidos.","example":"Le chat est noir. (O gato é preto.)"},{"case":"Para indicar algo de forma genérica ou não específica, use os artigos indefinidos.","example":"J''ai un frère. (Tenho um irmão.)"},{"case":"No plural, use ''les'' para definido e ''des'' para indefinido.","example":"Les livres sont bons. (Os livros são bons.) / J''ai des amis. (Tenho uns amigos.)"},{"case":"O artigo ''l'''' é usado antes de vogal ou h mudo.","example":"l''école (a escola), l''homme (o homem)"}]'::jsonb, '[{"correction":"Use ''un'' para substantivos masculinos, mesmo que terminem em -e.","mistake":"Confundir o gênero: ''une ami'' (errado) -> ''un ami'' (certo). Ami é masculino."},{"correction":"Sempre use ''les'' no plural definido e ''des'' no plural indefinido.","mistake":"Esquecer o plural do artigo: ''le enfants'' (errado) -> ''les enfants'' (certo)."},{"correction":"Memorize o gênero das palavras; o artigo ajuda a identificar.","mistake":"Aplicar a regra do ''e'' final para todos os substantivos: ''un problème'' é masculino mesmo terminando em ''e''."}]'::jsonb, '["Diferente do português, os substantivos em francês têm gênero que precisa ser memorizado; porém, muitas vezes o artigo revela o gênero.","No plural, o ''s'' final geralmente não é pronunciado, mas os artigos mudam: un -> des; le/la -> les.","Cuidado com palavras que são masculinas em português e femininas em francês, e vice-versa."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

