insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-fr-a1-4b73a5c3e0ee', 'fr', 'A1', 'Gênero, Número e Artigos em Francês', 'Nesta lição, você vai aprender a identificar o gênero (masculino/feminino) e o número (singular/plural) dos substantivos em francês e a usar os artigos definidos e indefinidos corretamente. Isso é essencial para formar frases básicas e se comunicar no dia a dia.', 'Em francês, os substantivos são masculinos ou femininos. No singular, use ''le'' para masculino e ''la'' para feminino. No plural, use ''les'' para ambos. Os artigos indefinidos são ''un'' (masculino), ''une'' (feminino) e ''des'' (plural). Para formar o plural, normalmente adiciona-se ''s'' ao substantivo: ''un livre'' → ''des livres'', ''une table'' → ''des tables''. Alguns substantivos não mudam no plural: ''un pois'' → ''des pois''. Palavras terminadas em ''-eau'' ganham ''x'' no plural: ''un chapeau'' → ''des chapeaux''.', '["Use o artigo definido (le/la/les) para falar de algo específico ou já mencionado.","Use o artigo indefinido (un/une/des) para apresentar algo pela primeira vez ou falar de algo não específico.","Use ''les'' e ''des'' para o plural, independentemente do gênero.","Em francês, não usamos artigo antes de profissões, nacionalidades e religiões em certos contextos: ''Il est médecin''."]'::jsonb, '["Confundir o gênero: ''le table'' em vez de ''la table''.","Usar artigo singular com plural: ''les livre'' em vez de ''les livres''.","Usar ''un'' com plural: ''un livres'' em vez de ''des livres''.","Aplicar sempre -s no plural, ignorando exceções como ''chapeaux''."]'::jsonb, '["Aprenda o substantivo já com o artigo: ''la chaise'', ''le bureau''.","O gênero pode ser diferente do português: ''le lait'' (o leite) é masculino; ''la mer'' (o mar) é feminino.","No plural, o artigo não muda entre masculino e feminino: ''les enfants'' (meninos ou meninas).","Em francês, ''des'' é usado no plural indefinido, mas também pode ser a contração de ''de + les'' em outros contextos."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

