insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-fr-a1-3c8894a359c2', 'fr', 'A1', 'Les articles, le genre et le nombre en français', 'Na língua francesa, todos os substantivos têm gênero (masculino ou feminino) e número (singular ou plural). Os artigos (le, la, les, un, une, des) são palavras que acompanham os substantivos e concordam com eles. Para um aluno brasileiro, é importante notar que o gênero das palavras em francês nem sempre coincide com o do português. É essencial conhecer o gênero de cada substantivo para usar o artigo correto.', 'Os artigos definidos são: le (masculino singular), la (feminino singular) e les (plural para ambos os gêneros). Os artigos indefinidos são: un (masculino singular), une (feminino singular) e des (plural para ambos). Para formar o plural dos substantivos, normalmente adiciona-se -s: ex., ‘livre’ (livro) → ‘livres’. Para formar o feminino, adiciona-se -e: ex., ‘ami’ (amigo) → ‘amie’ (amiga).', '["Usamos ‘le/la’ para falar de algo específico ou já conhecido: ‘le livre’ (o livro específico).","Usamos ‘un/une’ para apresentar algo novo ou não específico: ‘un livre’ (um livro qualquer).","Usamos ‘les’ para um grupo específico no plural: ‘les enfants’ (as crianças de um grupo).","Usamos ‘des’ para um grupo não específico no plural: ‘des enfants’ (umas crianças, algumas crianças)."]'::jsonb, '["Confundir gênero: muitos substantivos masculinos em português são femininos em francês, como ‘souris’ (rato) que é feminino.","Usar o artigo errado para o plural: não usar ‘les’ quando a ideia é específica.","Esquecer de pluralizar o substantivo junto com o artigo: ‘les chat’ em vez de ‘les chats’."]'::jsonb, '["Em francês, o substantivo carrega seu gênero intrínseco; é preciso memorizá-lo, pois não há regra geral para todas as palavras.","No plural, além do -s final, há exceções como ‘cheval’ → ‘chevaux’. Vamos ver isso mais adiante.","Esteja atento: ao contrário do português, o artigo definido pode ser omitido em algumas situações, mas em uso geral, deve aparecer."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

