insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-fr-a1-f155a772e4f4', 'fr', 'A1', 'Gênero, Número e Artigos em Francês', 'Nesta lição, você vai aprender como os substantivos em francês têm gênero (masculino ou feminino) e número (singular ou plural), e como usar os artigos definidos e indefinidos corretamente.', 'Em francês, o artigo concorda em gênero e número com o substantivo. Os artigos definidos são: le (masculino singular), la (feminino singular), les (plural). Os artigos indefinidos são: un (masculino singular), une (feminino singular), des (plural). Exemplos: le chat (o gato), la table (a mesa), les livres (os livros), un chat (um gato), une table (uma mesa), des livres (uns livros).', '["Use ''le'' para substantivos masculinos singulares: le garçon (o menino).","Use ''la'' para substantivos femininos singulares: la fille (a menina).","Use ''les'' para qualquer substantivo no plural: les garçons, les filles.","Use ''un'' para substantivos masculinos singulares indefinidos: un chien (um cachorro).","Use ''une'' para substantivos femininos singulares indefinidos: une maison (uma casa).","Use ''des'' para plural indefinido: des chiens (uns cachorros)."]'::jsonb, '["Confundir o gênero: em francês, ''livre'' é masculino (le livre), não feminino.","Usar ''des'' com artigo definido: ''les'' é definido, ''des'' é indefinido.","Esquecer a concordância: o artigo deve ter o mesmo gênero e número do substantivo.","Achar que todos os substantivos terminados em -e são femininos: ''le musée'' é masculino."]'::jsonb, '["Não existe gênero neutro em francês.","Alguns substantivos têm formas diferentes para masculino e feminino: ami/amie.","No plural, geralmente adiciona-se -s, mas a pronúncia muitas vezes não muda: le chat / les chats.","As contrações ''au'' e ''aux'' são usadas com preposições, veremos depois.","Para iniciantes, é importante memorizar o gênero com o artigo desde o início."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

