insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-fr-a1-0c528f39284a', 'fr', 'A1', 'Gênero e número dos artigos definidos e indefinidos', 'Em francês, os artigos (le, la, les, un, une, des) concordam em gênero (masculino ou feminino) e número (singular ou plural) com o substantivo. Para estudantes brasileiros, isso é parecido com o português, mas há diferenças importantes que exigem atenção. Nesta lição, você vai aprender a escolher o artigo certo em situações simples do dia a dia.', 'Existem dois grupos principais:

1. Artigos definidos (o, a, os, as):
   - le: masculino singular (ex: le livre – o livro)
   - la: feminino singular (ex: la chaise – a cadeira)
   - les: plural para masculino e feminino (ex: les livres – os livros; les chaises – as cadeiras)

2. Artigos indefinidos (um, uma, uns, umas):
   - un: masculino singular (ex: un chat – um gato)
   - une: feminino singular (ex: une pomme – uma maçã)
   - des: plural para masculino e feminino (ex: des chats – uns gatos; des pommes – umas maçãs)

Observação: antes de uma vogal ou h mudo, le e la viram l''. Exemplo: l''école (a escola), l''homme (o homem).', '["Usamos artigos definidos quando falamos de algo específico, já conhecido. Exemplo: Le livre est sur la table. (O livro está sobre a mesa.)","Usamos artigos indefinidos quando falamos de algo não específico, uma coisa qualquer. Exemplo: Un chien aboie. (Um cachorro late.)","Usamos les (definido) ou des (indefinido) para falar de vários itens. Exemplo: Les fleurs sont belles. (As flores são bonitas.) / J''ai des amis. (Tenho uns amigos.)"]'::jsonb, '["Confundir o gênero de palavras que são diferentes do português. Exemplo: le soleil (masculino) é ''o sol'' em português (masculino), mas la lune (feminino) é ''a lua'' (feminino). Sempre aprenda o substantivo com o seu artigo.","Usar un com palavras femininas ou une com palavras masculinas. Exemplo: une table (correto), não un table.","Esquecer a forma plural des ou les, usando o singular. Exemplo: des chaises, não *un chaises*.","Usar le ou la antes de vogal, em vez de l''. Exemplo: l''école, não *le école*."]'::jsonb, '["Dica: para saber o gênero de um substantivo em francês, preste atenção no final da palavra. Por exemplo, muitas palavras terminadas em -ette são femininas: la fillette, la bicyclette.","No plural, o artigo é mais importante que a terminação do substantivo, porque a pronúncia muitas vezes não muda (ex: le livre e les livres têm o mesmo som do substantivo).","Não confunda ''des'' com ''de les''. Em francês, não usamos ''de les'' junto; usamos ''des'' ou ''aux'', dependendo do contexto."]'::jsonb, 0, true)
