insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-fr-a1-f30b4afdb07b', 'fr', 'A1', 'Gênero, número e artigos em francês', 'Em francês, todos os substantivos têm gênero (masculino ou feminino) e número (singular ou plural). Os artigos definidos e indefinidos concordam com o substantivo em gênero e número. Nesta lição, você vai aprender as regras básicas para usar le, la, les, un, une e des corretamente.', 'Artigos definidos: le (masculino singular), la (feminino singular), les (plural para ambos os gêneros). Artigos indefinidos: un (masculino singular), une (feminino singular), des (plural para ambos os gêneros). Para formar o feminino dos substantivos, geralmente adiciona-se -e ao final (ex.: ami -> amie). Para formar o plural, geralmente adiciona-se -s (ex.: livre -> livres). O artigo deve sempre concordar com o substantivo.', '["Use le ou la para falar de algo específico ou já conhecido: Le livre est sur la table. (O livro está sobre a mesa.)","Use un ou une para algo não específico: J''ai un chien. (Tenho um cachorro.)","Use les para plural definido: Les enfants jouent. (As crianças brincam.)","Use des para plural indefinido: Je vois des oiseaux. (Vejo pássaros.)"]'::jsonb, '["Confundir le e la: lembre-se de que o gênero é uma característica do substantivo, não do objeto real.","Esquecer de mudar o artigo no plural: sempre use les ou des com substantivos no plural.","Usar un com substantivos femininos: verifique se o substantivo termina com -e, mas cuidado com exceções."]'::jsonb, '["A maioria dos substantivos terminados em -e são femininos, mas existem exceções (ex.: le musée).","O plural e o singular têm pronúncia idêntica na maioria dos casos; o artigo indica o número.","Em francês, não usamos artigos antes de profissões em certas construções, mas isso é um nível mais avançado.","Aprenda o gênero junto com o substantivo desde o início."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

