insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-fr-a1-51165d7a8dca', 'fr', 'A1', 'Gênero, número e artigos em francês', 'Em francês, todos os substantivos têm gênero (masculino ou feminino) e número (singular ou plural). Os artigos definidos e indefinidos devem concordar com o substantivo em gênero e número. Nesta lição, você vai aprender a usar corretamente os artigos.', 'Os artigos definidos são: le (masculino singular), la (feminino singular), les (plural para ambos os gêneros). Os artigos indefinidos são: un (masculino singular), une (feminino singular), des (plural para ambos os gêneros). Exemplos: le livre (o livro), la table (a mesa), les livres (os livros), un livre (um livro), une table (uma mesa), des livres (uns livros).', '["Usamos o artigo definido para falar de algo específico: ''le chat est noir'' (o gato é preto).","Usamos o artigo indefinido para falar de algo não específico: ''un chat'' (um gato qualquer).","No plural, usamos ''les'' para definido e ''des'' para indefinido: ''les chats'' (os gatos), ''des chats'' (uns gatos)."]'::jsonb, '["Confundir ''un'' e ''une'': lembre-se de que ''un'' é para masculino e ''une'' para feminino.","Esquecer o plural: use ''les'' ou ''des'' para mais de um item.","Achar que todos os substantivos terminados em ''-e'' são femininos: há exceções."]'::jsonb, '["Existem dicas para identificar o gênero: substantivos terminados em ''-age'' são geralmente masculinos; ''-tion'' são geralmente femininos.","Não há neutro em francês: todo substantivo é masculino ou feminino.","O artigo indefinido plural ''des'' vira ''de'' antes de adjetivo plural: ''des amis'' -> ''de bons amis''."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

