insert into public.grammar_exercises (id, language, level, title, explanation, example, question, options, answer_index, sort_order, is_published, topic_id)
values ('generated-grammar-fr-a1-51165d7a8dca-exercise-05', 'fr', 'A1', 'Exercício 5', 'O substantivo ''livre'' (livro) é masculino singular, portanto o artigo definido correto é ''le''. ''Les'' é plural, ''la'' é feminino, e ''un'' é indefinido, não se encaixando na definição.', 'Qual das frases usa o artigo definido corretamente para o substantivo ''livre'' (livro)?', 'Qual das frases usa o artigo definido corretamente para o substantivo ''livre'' (livro)?', '["La livre est sur la table.","Le livre est sur la table.","Les livre est sur la table.","Un livre est sur la table."]'::jsonb, 1, 5, true, 'generated-grammar-fr-a1-51165d7a8dca')
