insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-fr-a1-164da606b780', 'fr', 'A1', 'Artigos Definidos e Indefinidos: Gênero e Número', 'Em francês, os artigos concordam em gênero (masculino ou feminino) e número (singular ou plural) com o substantivo. Existem dois tipos principais: artigos definidos (le, la, les) e indefinidos (un, une, des). Nesta lição, você vai aprender a escolher a forma correta do artigo.', 'Artigos definidos: le (masculino singular), la (feminino singular), les (plural). Exemplos: le livre (o livro), la maison (a casa), les livres (os livros). Artigos indefinidos: un (masculino singular), une (feminino singular), des (plural). Exemplos: un livre (um livro), une maison (uma casa), des livres (uns livros / livros).', '["Usamos le, la, les para falar de algo específico ou conhecido: le chat est noir (o gato é preto).","Usamos un, une, des para algo não específico: un chat (um gato).","No plural, usamos les para definido e des para indefinido.","Atenção: antes de vogal ou h mudo, le e la viram l'': l''école (a escola), l''homme (o homem)."]'::jsonb, '["Não confundir le (masculino) com la (feminino): la maison é feminino, então le maison está errado.","Esquecer de usar des no plural indefinido: escrever ''un livres'' no lugar de ''des livres''.","Usar le, la antes de vogal: l''école, não le école.","Achar que o gênero em português é igual ao francês: em francês, ''livre'' é masculino (le livre), mas em português ''livro'' é masculino."]'::jsonb, '["Aprenda o gênero junto com a palavra: não memorize apenas ''maison'', memorize ''la maison''.","A maioria dos substantivos terminados em -e são femininos, mas há exceções.","As palavras que começam com vogal ou h mudo usam l'' no singular definido.","Para o plural de un/une, usamos des: des maisons (umas casas / casas)."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

