insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-fr-a1-98e6cedae5e6', 'fr', 'A1', 'Gênero, número e artigos no francês A1', 'Em francês, todo substantivo é masculino ou feminino, e está no singular ou no plural. Os artigos (le, la, les, un, une, des) mudam de acordo com o gênero e o número do substantivo. Nesta lição, você vai aprender a identificar e usar essas formas essenciais.', 'Para o plural, geralmente acrescentamos -s ao substantivo e ao artigo. Para o feminino, muitos substantivos recebem -e no final. Exemplos: un ami (um amigo) → une amie (uma amiga) → des amis (amigos). O artigo definido tem as formas le (masculino), la (feminino), les (plural). O artigo indefinido tem un (masculino), une (feminino), des (plural).', '["Use ''le'' ou ''la'' para falar de algo específico: ''Le livre est sur la table.''","Use ''un'' ou ''une'' para apresentar algo pela primeira vez: ''C''est un chat.''","Use ''les'' e ''des'' para falar de várias coisas: ''Les enfants jouent.''","Use ''la'' antes de substantivos femininos como ''maison'', ''fille'', ''école''.","Use ''le'' antes de substantivos masculinos como ''garçon'', ''livre'', ''chien''."]'::jsonb, '["Usar ''le'' com substantivo feminino: *le fille (errado) → la fille (correto).","Usar ''un'' no plural: *un amis (errado) → des amis (correto).","Esquecer o -s no plural do substantivo: *les chat (errado) → les chats (correto).","Trocar ''des'' por ''les'' para algo indefinido no plural."]'::jsonb, '["Antes de vogal ou h mudo, use l'' no lugar de le/la: l''école.","Alguns substantivos têm feminino irregular: un homme → une femme.","A pronúncia do ''s'' final do plural geralmente não é pronunciada: chats = \"châ\".","Em francês, não existe neutro."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

