insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-fr-a1-f7e1969dee96', 'fr', 'A1', 'Gênero e número: artigos definidos e indefinidos', 'Em francês, os substantivos têm gênero (masculino ou feminino) e número (singular ou plural). Os artigos definidos (le, la, les) e indefinidos (un, une, des) concordam com o substantivo em gênero e número. Nesta lição, você vai aprender as formas básicas para usar corretamente os artigos no dia a dia.', 'Masculino singular: le (definido) / un (indefinido). Feminino singular: la (definido) / une (indefinido). Plural (masculino ou feminino): les (definido) / des (indefinido). Exemplos: le chat (o gato), la chatte (a gata), les chats (os gatos), des chats (uns gatos).', '["Usamos ''le'' com substantivos masculinos singulares: le livre, le garçon, le chien.","Usamos ''la'' com substantivos femininos singulares: la maison, la fille, la voiture.","Usamos ''les'' para o plural de ambos os gêneros: les livres, les maisons.","Usamos ''des'' para o plural indefinido: des livres, des maisons.","Para saber o gênero, é comum observar a terminação: -e costuma ser feminino, mas há muitas exceções."]'::jsonb, '["Trocar ''le'' por ''la'' ou vice-versa. Sempre aprenda o substantivo com o artigo.","Usar ''un'' com substantivos femininos, por exemplo, ''un maison''. O correto é ''une maison''.","Esquecer de usar ''les'' ou ''des'' no plural. Em português, às vezes omitimos o artigo, mas em francês é obrigatório.","Confundir ''des'' com ''les''. ''les'' é definido, ''des'' é indefinido."]'::jsonb, '["Diante de vogal ou ''h'' mudo, ''le'' e ''la'' viram ''l'' (ex.: l''ami, l''école).","Não há artigo neutro em francês.","Alguns substantivos mudam de sentido com o gênero: le livre (o livro), la livre (a libra).","Os adjetivos também concordam, mas isso será visto em outra lição."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

