insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-fr-a1-0f5749ae26d0', 'fr', 'A1', 'Artigos definidos e indefinidos: gênero e número', 'Nesta lição, você vai aprender a usar os artigos definidos (le, la, les) e indefinidos (un, une, des) em francês. Eles mudam conforme o gênero (masculino ou feminino) e o número (singular ou plural) do substantivo.', 'Artigos definidos:
- le (masculino singular): le garçon (o menino)
- la (feminino singular): la fille (a menina)
- les (plural para ambos): les garçons (os meninos), les filles (as meninas)

Artigos indefinidos:
- un (masculino singular): un garçon (um menino)
- une (feminino singular): une fille (uma menina)
- des (plural para ambos): des garçons (uns meninos), des filles (umas meninas)

Dica: Antes de vogal ou ''h'' mudo, le e la viram l'': l''ami (o amigo), l''école (a escola).', '["Usamos artigos definidos para falar de algo específico ou já conhecido: Le livre est sur la table. (O livro está sobre a mesa.)","Usamos artigos indefinidos para apresentar algo ou falar de algo não específico: J''ai un chien. (Eu tenho um cachorro.)","Les é usado para plural, independentemente do gênero: Les élèves sont contents. (Os alunos estão contentes.)","Des é o plural de un e une: Il y a des fleurs. (Há umas flores.)"]'::jsonb, '["Esquecer a concordância: ''la livre'' (errado) → ''le livre'' (certo), pois ''livre'' é masculino.","Usar ''les'' para singular: ''Les chat'' (errado) → ''Le chat'' (certo).","Confundir ''un'' e ''une'': ''une vélo'' (errado) → ''un vélo'' (certo), pois ''vélo'' é masculino.","Usar ''des'' para um só objeto: ''des livre'' (errado) → ''un livre'' ou ''une livre'' (dependendo do gênero)."]'::jsonb, '["O gênero dos substantivos nem sempre é igual ao português. Por exemplo, ''livre'' é masculino em francês e feminino em português.","Quando o adjetivo concorda com o gênero e número: une grande maison (uma casa grande), de grandes maisons (umas casas grandes).","Em francês, não existe artigo definido neutro."]'::jsonb, 0, true)
