insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-fr-a1-2739320cc5d2', 'fr', 'A1', 'Le genre, le nombre et les articles', 'Nesta lição, você vai aprender sobre o gênero (masculino/feminino) e o número (singular/plural) dos substantivos em francês, e como usar os artigos definidos (le, la, les) e indefinidos (un, une, des). Vai perceber que os artigos mudam de forma para concordar com o substantivo.', 'Em francês, os substantivos têm gênero: masculino ou feminino. Para o singular, o artigo definido masculino é ''le'' e o feminino é ''la''. O artigo indefinido masculino é ''un'' e o feminino é ''une''. No plural, usamos ''les'' para o definido e ''des'' para o indefinido, sem distinção de gênero. Exemplos: le livre (o livro), la table (a mesa), les livres (os livros), les tables (as mesas), un livre (um livro), une table (uma mesa), des livres (uns livros), des tables (umas mesas). Para transformar um substantivo do masculino para o feminino, geralmente adicionamos -e: ami (amigo) -> amie (amiga). Para o plural, geralmente adicionamos -s: ami -> amis. Cuidado com exceções.', '["Usamos ''le'' e ''la'' para falar de algo específico ou já conhecido: ''Le livre est sur la table.'' (O livro está na mesa.)","Usamos ''un'' e ''une'' para apresentar algo não específico: ''J''ai un livre.'' (Eu tenho um livro.)","Usamos ''les'' e ''des'' para o plural: ''Les enfants jouent.'' (As crianças brincam), ''Des enfants jouent.'' (Umas crianças brincam.)","Quando o substantivo começa com vogal ou h mudo, ''le'' e ''la'' viram ''l'' : l''école (a escola)."]'::jsonb, '["Não se baseie no gênero da palavra em português; aprenda o gênero de cada palavra junto com o artigo.","Esquecer de usar o artigo antes do substantivo: ''chat est noir'' (errado) em vez de ''le chat est noir''.","Usar ''des'' com palavra no singular: ''des livre'' (errado) em vez de ''un livre''.","Após a negativa, ''des'' vira ''de'': ''Je n''ai pas de livre.'' (Não tenho livro)."]'::jsonb, '["Em francês, todos os substantivos têm gênero, inclusive objetos e ideias.","O artigo definido é usado com preferências e hábitos: ''J''aime le chocolat.''","Na forma negativa, os artigos indefinidos ''un'', ''une'', ''des'' geralmente mudam para ''de'' ou ''d''''.","Cuidado com a elisão: ''le'' e ''la'' viram ''l'' antes de vogal ou h mudo."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

