insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-fr-a1-10d6f0fe0014', 'fr', 'A1', 'Gênero, número e artigos em francês', 'Em francês, os substantivos têm gênero (masculino ou feminino) e número (singular ou plural). Os artigos definidos (le, la, les) e indefinidos (un, une, des) mudam conforme o gênero e o número. Para adultos brasileiros iniciantes, é essencial aprender essas regras desde o início, pois elas afetam toda a frase.', 'Artigos definidos: le (masculino singular), la (feminino singular), les (plural definido). Artigos indefinidos: un (masculino singular), une (feminino singular), des (plural indefinido). No plural, não distinguimos gênero. Exemplos: le livre (o livro), la maison (a casa), les livres (os livros), un chat (um gato), une chaise (uma cadeira), des chats (gatos).', '["Usamos os artigos definidos para falar de algo específico ou já conhecido.","Usamos os artigos indefinidos para falar de algo não específico ou mencionado pela primeira vez.","Usamos le/la/les antes de substantivos que indicam categorias, preferências etc.","Usamos un/une/des para indicar quantidades ou elementos indefinidos."]'::jsonb, '["Confundir o gênero dos substantivos: em francês, muitas palavras têm gênero diferente do português.","Usar ''des'' como artigo definido no plural: ''des'' é indefinido, o definido é ''les''.","Esquecer de usar o artigo antes de substantivos: em francês, geralmente é obrigatório.","Aplicar a mesma regra de gênero do português: não há correspondência sistemática."]'::jsonb, '["Aprenda cada substantivo com seu artigo: le/la, e o plural com les/des.","Atenção às contrações: ''le'' + ''à'' = ''au'', ''les'' + ''à'' = ''aux'', etc. (nível mais avançado).","Substantivos que começam com vogal ou h mudo fazem elisão: l’ami, l’école.","No plural, o ''s'' geralmente não é pronunciado, então o artigo indica o número."]'::jsonb, 0, true)
