insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-fr-a1-bcc6fe63cda9', 'fr', 'A1', 'Gênero, número e artigos: le, la, un, une, les, des', 'Em francês, todo substantivo tem gênero (masculino ou feminino) e número (singular ou plural). Os artigos definidos e indefinidos concordam com o substantivo em gênero e número. Aprender os artigos junto com os substantivos é essencial para falar corretamente.', 'Artigos definidos: le (masculino singular), la (feminino singular), les (plural, ambos os gêneros). Artigos indefinidos: un (masculino singular), une (feminino singular), des (plural, ambos os gêneros). Antes de vogal ou h mudo, le e la se tornam l'' (ex.: l''homme, l''école).', '["Use ''le'' ou ''un'' com substantivos masculinos: le livre, un chien.","Use ''la'' ou ''une'' com substantivos femininos: la maison, une femme.","Use ''les'' para falar de um grupo específico ou já conhecido: les enfants (as crianças).","Use ''des'' para falar de um grupo não específico: des enfants (umas crianças)."]'::jsonb, '["Não confundir ''les'' (plural definido) com ''des'' (plural indefinido): ''Je vois les chiens'' (os cães) vs. ''Je vois des chiens'' (uns cães).","Esquecer que ''le'' e ''la'' viram ''l'''' antes de vogal: ''la école'' é errado; o correto é ''l''école''.","Achar que todo substantivo terminado em ''e'' é feminino. Muitos são masculinos, como ''le livre'' e ''le musée''.","Usar ''un'' com substantivo feminino ou ''une'' com masculino. É preciso memorizar o gênero."]'::jsonb, '["O plural dos substantivos geralmente é marcado com -s, mas esse -s não é pronunciado.","Aprenda cada substantivo com seu artigo: ''le livre'', ''la table''.","Os artigos são muito usados em francês; evite omiti-los.","L'' é usado apenas no singular, para le/la, independentemente do gênero."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

