insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-fr-a1-f97313655ffc', 'fr', 'A1', 'Artigos definidos e indefinidos: gênero e número', 'Em francês, os substantivos têm gênero (masculino ou feminino) e número (singular ou plural). Os artigos definidos (o, a, os, as) e indefinidos (um, uma, uns, umas) precisam concordar com o substantivo. Nesta lição, você aprenderá a usar os artigos mais comuns do francês.', 'Artigos definidos: le (masculino singular), la (feminino singular), l'' (antes de vogal ou h mudo), les (plural para ambos os gêneros).
Exemplos: le livre, la maison, l''école, les livres, les maisons.

Artigos indefinidos: un (masculino singular), une (feminino singular), des (plural para ambos os gêneros).
Exemplos: un livre, une maison, des livres, des maisons.', '["Artigos definidos indicam algo específico ou já conhecido: Le livre est sur la table.","Também usamos o artigo definido para falar de algo em geral: J''aime le café.","Artigos indefinidos apresentam algo não específico: J''ai un chien.","No plural, des indica uma quantidade indefinida: Il y a des fleurs."]'::jsonb, '["Usar ''un'' com substantivo feminino: ''Elle a un copine'' → correto: ''Elle a une copine''.","Esquecer a elisão com vogal: ''la école'' → correto: ''l''école''.","Trocar ''les'' por ''des'' em contexto específico: ''Les livres sont ici'' e não ''Des livres sont ici''.","Achar que ''h'' mudo é sempre masculino ou feminino: ''un homme'' é masculino, ''une habitude'' é feminino."]'::jsonb, '["No plural, não há distinção de gênero: les e des servem para masculino e feminino.","A elisão ocorre com vogais e com o h mudo: l''amie, l''école, l''hôtel.","Cuidado: o plural de un/une é des, mas em frases negativas forma-se ''de'' (uso mais avançado, veremos depois).","Ao aprender o vocabulário, memorize o artigo junto com o substantivo, como se fosse uma única unidade."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

