insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-fr-a1-96aff0c03a4d', 'fr', 'A1', 'Gênero, número e artigos em francês', 'Em francês, todo substantivo tem um gênero (masculino ou feminino) e um número (singular ou plural). Os artigos definidos e indefinidos concordam com o substantivo em gênero e número. Nesta lição, você vai aprender a usar corretamente le, la, les, un, une e des.', 'Artigos definidos: le (masculino singular), la (feminino singular), les (plural). Antes de vogal ou h mudo, usa-se l'' (ex.: l''homme, l''école). Artigos indefinidos: un (masculino singular), une (feminino singular), des (plural).', '["Usamos le/la/les para falar de algo específico ou já conhecido: J''aime le chocolat.","Usamos un/une/des para apresentar algo pela primeira vez ou falar de algo de forma indefinida: J''ai une idée.","Usamos les para generalizar: Les chiens sont intelligents.","Usamos des para indicar uma quantidade não especificada: Je voudrais des pommes."]'::jsonb, '["Confundir o gênero dos substantivos: dizer ''le table'' em vez de ''la table''.","Usar ''un'' com substantivo feminino: ''un chaise'' em vez de ''une chaise''.","Esquecer a concordância do artigo no plural: ''les livre'' em vez de ''les livres''.","Usar ''des'' com substantivo singular: ''des livre'' em vez de ''des livres''."]'::jsonb, '["Aprenda o gênero junto com o substantivo: sempre memorize ''le livre'' e ''la page''.","O plural geralmente é formado acrescentando -s ao substantivo.","Antes de vogal ou h mudo, le e la viram l'': l''ami, l''école.","Em frases negativas, os artigos indefinidos un, une e des mudam para de: ''Je n''ai pas de chien.''"]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

