insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-fr-a1-dd83abff115a', 'fr', 'A1', 'Gênero e número dos substantivos e artigos em francês', 'Nesta lição, você vai aprender como identificar o gênero (masculino ou feminino) e o número (singular ou plural) dos substantivos em francês, e como usar os artigos definidos e indefinidos corretamente.', 'Em francês, os substantivos têm gênero (masculino ou feminino) e número (singular ou plural). Os artigos definidos são: le (masculino singular), la (feminino singular), les (plural). Os artigos indefinidos são: un (masculino singular), une (feminino singular), des (plural). Para formar o plural, normalmente acrescenta-se -s ao substantivo: un livre → des livres, une maison → des maisons. Alguns substantivos não seguem essa regra, mas por enquanto usamos a forma geral.', '["Para falar de algo específico ou já conhecido, use le/la/les: le livre (o livro), la table (a mesa), les livres (os livros).","Para apresentar algo pela primeira vez ou algo não específico, use un/une/des: un livre (um livro), une table (uma mesa), des livres (alguns livros).","Para identificar o gênero, observe terminações: -age, -ment, -eau costumam ser masculinos; -tion, -sion, -ette, -ance costumam ser femininos.","Concorde sempre o artigo com o substantivo em gênero e número: le café (masc.), la maison (fem.), les enfants (plural)."]'::jsonb, '["Usar le com substantivos femininos: ''le maison'' (errado), o correto é ''la maison''.","Esquecer o -s no plural: ''des livre'' (errado), o correto é ''des livres''.","Confundir un/une: ''un table'' (errado), o correto é ''une table''.","Usar les no singular: ''les livre'' (errado), o correto é ''le livre'' ou ''les livres''."]'::jsonb, '["Não existe artigo neutro em francês.","Palavras terminadas em -e são frequentemente femininas, mas há exceções: le musée (masculino).","Alguns substantivos mudam de forma: un acteur → une actrice.","No plural, o -s final geralmente não é pronunciado.","Os artigos definidos fazem contração com à e de, mas isso será estudado depois."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

