insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-fr-a1-85b79f9f0ca8', 'fr', 'A1', 'Gênero e Número: Artigos Definidos e Indefinidos', 'Nesta lição, vamos aprender como identificar o gênero (masculino/feminino) e o número (singular/plural) dos substantivos em francês, e como usar os artigos definidos (le, la, les) e indefinidos (un, une, des) de forma correta.', 'Em francês, os substantivos têm gênero: masculino ou feminino. O artigo definido singular é ''le'' para masculino, ''la'' para feminino. Antes de vogal ou h mudo, usa-se ''l''''. O plural para ambos é ''les''. O artigo indefinido singular é ''un'' para masculino e ''une'' para feminino. O plural é ''des''.', '["Para falar de algo já conhecido ou específico, usamos os artigos definidos: le (masculino), la (feminino), les (plural).","Para apresentar algo pela primeira vez ou falar de algo não específico, usamos os artigos indefinidos: un (masculino), une (feminino), des (plural).","Antes de vogal ou h mudo, o artigo definido singular se torna l'' (ex: l''école, l''homme).","No plural, não há distinção de gênero para os artigos: les (definido) e des (indefinido)."]'::jsonb, '["Usar ''un'' com substantivo feminino ou ''une'' com masculino. Ex.: ''un maison'' (errado) vs ''une maison'' (correto).","Esquecer de usar o artigo plural ''les'' para substantivos no plural. Ex.: ''des chats'' ou ''les chats'', dependendo do contexto.","Usar ''les'' como artigo indefinido no plural. Lembre-se: ''les'' é definido, ''des'' é indefinido."]'::jsonb, '["O plural de substantivos em francês geralmente é formado com -s, mas essa letra não é pronunciada.","Para saber o gênero de um substantivo, é importante consultar o dicionário. Não existe regra única.","Muitos substantivos terminados em -e são femininos, mas há exceções como ''musée'' (masculino)."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

