insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-fr-a1-08ee025d1b97', 'fr', 'A1', 'Gênero e número dos substantivos: artigos definidos e indefinidos', 'Nesta lição, você vai aprender como os substantivos em francês têm gênero (masculino ou feminino) e número (singular ou plural) e como os artigos definidos (le, la, l'', les) e indefinidos (un, une, des) mudam de acordo com eles. Isso é essencial para formar frases corretas no nível A1.', 'Em francês, o artigo definido singular é ''le'' para masculino e ''la'' para feminino. Antes de vogal ou ''h'' mudo, usa-se ''l''''. No plural, usa-se ''les'' para os dois gêneros. O artigo indefinido singular é ''un'' para masculino e ''une'' para feminino. No plural, usa-se ''des''. O plural dos substantivos normalmente é formado acrescentando ''s''.', '["Para falar de algo específico ou já conhecido: ''le livre'' (o livro), ''la maison'' (a casa).","Para apresentar algo pela primeira vez: ''un chat'' (um gato), ''une pomme'' (uma maçã).","Para falar de algo em geral: ''J''aime le café'' (Eu gosto de café).","Para falar de uma quantidade indefinida: ''J''ai des amis'' (Eu tenho amigos)."]'::jsonb, '["Confundir o gênero do português com o francês: em português ''a mesa'', em francês ''la table'' (feminino), mas ''le livre'' (masculino) apesar de ''o livro''.","Usar ''un'' com substantivos femininos: *''un fille'' é errado; o correto é ''une fille''.","Esquecer o artigo antes do substantivo: *''chat est noir'' é errado; o correto é ''le chat est noir''.","No plural, esquecer de usar ''les'' ou ''des'': *''livres sont bons'' é errado; o correto é ''les livres sont bons''.","Usar ''l'''' antes de consoante: *''l''chat'' é errado; o correto é ''le chat''."]'::jsonb, '["O artigo ''l'''' é usado antes de substantivos que começam com vogal ou ''h'' mudo, independente do gênero: ''l''école'' (a escola), ''l''homme'' (o homem).","Alguns substantivos não seguem a regra do plural em -s: ''un cheveu'' -> ''des cheveux'' (cabelos), ''un jeu'' -> ''des jeux'' (jogos).","Os substantivos que terminam em -s, -x ou -z não mudam no plural: ''un pays'' -> ''des pays''.","Na negação, os artigos indefinidos ''un'', ''une'' e ''des'' mudam para ''de'' ou ''d'''' (ex.: ''Je n''ai pas de chat''), mas isso será estudado mais adiante.","O gênero dos substantivos em francês é geralmente aprendido por memorização; use o dicionário para verificar."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

