insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-fr-a1-ca02eb912742', 'fr', 'A1', 'Gênero e número: artigos definidos e indefinidos (A1)', 'Em francês, todo substantivo tem gênero (masculino ou feminino) e número (singular ou plural). Os artigos concordam com o gênero e o número do substantivo. Em português também usamos artigos, mas existem diferenças importantes, como o artigo definido plural ''les'' e o indefinido plural ''des''.', 'Artigos definidos: le (masculino singular), la (feminino singular), l'' (antes de vogal ou h mudo), les (plural). Artigos indefinidos: un (masculino singular), une (feminino singular), des (plural). Para formar o plural dos substantivos, geralmente acrescenta-se -s. Exceções comuns: ex.: animal -> animaux, cadeau -> cadeaux. Os artigos ''les'' e ''des'' são usados tanto para masculino quanto para feminino no plural.', '["Parler d''une chose connue : Voici le livre dont je t''ai parlé.","Parler d''une chose indéfinie : J''ai un livre.","Parler du pluriel de façon générale : Les chats sont mignons.","Indiquer une quantité indéfinie au pluriel : Je voudrais des pommes."]'::jsonb, '["Usar ''un'' com substantivo feminino (ex.: un maison) em vez de ''une maison''.","Esquecer o apóstrofo: ''le école'' em vez de ''l''école''.","Confundir ''les'' (definido plural) com ''des'' (indefinido plural): ''J''aime les livres'' vs ''Je lis des livres''.","Usar ''les'' com verbo no singular: ''Les amis est là'' em vez de ''Les amis sont là''."]'::jsonb, '["O gênero dos substantivos em francês nem sempre é lógico; aprenda cada palavra com seu artigo.","Profissões frequentemente têm formas femininas (ex.: professeur -> professeure).","As cores também funcionam como adjetivos e concordam em gênero e número.","Não confunda ''des'' com ''de les'': em francês moderno, ''des'' é a contração."]'::jsonb, 0, true)
