insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-fr-a1-7effb8353620', 'fr', 'A1', 'Gênero, número e artigos em francês', 'Nesta lição, você vai aprender como identificar o gênero (masculino/feminino) e o número (singular/plural) dos substantivos em francês, além de usar corretamente os artigos definidos (le, la, les) e indefinidos (un, une, des).', 'Em francês, os substantivos têm gênero: masculino (un livre) ou feminino (une table). O plural geralmente forma-se acrescentando -s ao substantivo: un livre -> des livres; la table -> les tables. Os artigos definidos são: le (masculino singular), la (feminino singular), les (plural). Os indefinidos: un (masculino singular), une (feminino singular), des (plural).', '["Use le, la, les para falar de algo específico ou já conhecido.","Use un, une, des para falar de algo não específico ou pela primeira vez.","No plural, o artigo definido é sempre ''les'' e o indefinido ''des''.","O gênero do substantivo determina o artigo singular."]'::jsonb, '["Confundir o gênero de palavras como ''livre'' (masculino) e ''table'' (feminino).","Esquecer de usar ''les'' para plural definido e usar ''le'' ou ''la'' no plural.","Achar que todos os substantivos terminados em -e são femininos (ex: ''lycée'' é masculino).","Usar ''des'' para plural indefinido apenas quando há quantidade indefinida; é o equivalente de ''uns/umas''."]'::jsonb, '["Dica: a maioria dos substantivos terminados em -e são femininos, mas isso não é uma regra absoluta.","O artigo indefinido no plural ''des'' significa ''uns/umas'' ou ''alguns/algumas''.","No plural, os artigos definidos e indefinidos perdem a distinção de gênero: les e des."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

