insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-fr-a1-fc60e5f7ec77', 'fr', 'A1', 'Gênero, número e artigos em francês', 'Em francês, todo substantivo é masculino ou feminino. Essa informação é essencial para escolher o artigo certo. Além disso, os artigos mudam no plural. Nesta lição, você vai aprender a usar le, la, l'', les, un, une e des com substantivos no singular e no plural.', 'Feminino: geralmente, adicionamos -e ao masculino. Exemplo: ami → amie. Plural: geralmente, adicionamos -s. Exemplo: ami → amis. Artigos definidos: le (masculino singular), la (feminino singular), l'' (antes de vogal), les (plural). Artigos indefinidos: un (masculino singular), une (feminino singular), des (plural). No plural, não há distinção de gênero nos artigos.', '["Usamos le ou la para falar de algo específico ou que já foi mencionado.","Usamos un ou une para apresentar algo pela primeira vez.","Usamos les para o plural de le e la.","Usamos des para o plural de un e une.","O artigo deve concordar com o gênero e o número do substantivo: le garçon, la fille, les garçons, les filles."]'::jsonb, '["Esquecer de usar artigo antes do substantivo: dizemos le livre, não apenas livre.","Confundir le e la: le é masculino, la é feminino. Ex.: le livre, la table.","Esquecer a forma contractada l'' antes de vogal: l''école, não la école.","Usar des com substantivo singular: des chat (errado) → des chats (correto).","Achar que todo substantivo terminado em -e é feminino: le musée é masculino."]'::jsonb, '["O gênero em francês nem sempre corresponde ao gênero em português.","A pronúncia do plural geralmente não muda: livre e livres soam quase iguais.","Alguns femininos são irregulares: beau → belle, vieux → vieille.","Em frases negativas, usamos pas de antes do substantivo: je n''ai pas de chats."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

