insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-fr-a1-dc7bf84cce28', 'fr', 'A1', 'Les articles : le, la, les, un, une, des', 'Nesta lição, você vai aprender a usar os artigos definidos e indefinidos em francês, e como eles mudam de acordo com o gênero (masculino ou feminino) e o número (singular ou plural). Vamos praticar com nomes de objetos, pessoas e animais.', 'Em francês, os artigos definidos são: le (masculino singular), la (feminino singular), les (masculino ou feminino plural). Os artigos indefinidos são: un (masculino singular), une (feminino singular), des (plural). Exemplos: le chat (o gato), la pomme (a maçã), les livres (os livros), un ami (um amigo), une école (uma escola), des enfants (crianças).', '["Use o artigo definido para falar de algo específico: le livre que je lis (o livro que estou lendo).","Use o artigo indefinido para falar de algo não específico: un livre (um livro qualquer).","No plural, use les para definido e des para indefinido: les amis (os amigos), des amis (alguns amigos).","Não use artigo antes de profissões e nacionalidades depois do verbo être: Je suis brésilien. (Sou brasileiro.)"]'::jsonb, '["Confundir o gênero: ''un table'' está errado. O correto é ''une table'', pois ''table'' é feminino.","Esquecer a concordância de número: ''le livres'' está errado. O correto é ''les livres''.","Usar artigo definido para algo genérico em contextos onde o francês usa indefinido: ''J''ai un chat'' e não ''J''ai le chat'' (a menos que seja específico)."]'::jsonb, '["Em francês, o artigo é geralmente obrigatório antes do substantivo.","Cuidado com as exceções: palavras que começam com vogal ou h mudo usam ''l'' no singular definido, como l''homme (o homem)."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

