values ('generated-grammar-fr-a1-dc7bf84cce28-exercise-05', 'fr', 'A1', 'Exercício 5', 'Em francês, quando falamos de profissões com o verbo ''être'', não usamos artigo. O correto é ''Je suis professeur''.', 'Qual frase está correta?', 'Qual frase está correta?', '["Je suis un professeur.","Je suis une professeur.","Je suis le professeur.","Je suis professeur."]'::jsonb, 3, 5, true, 'generated-grammar-fr-a1-dc7bf84cce28')
