insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-fr-a1-a11372db93e4', 'fr', 'A1', 'Gênero, Número e Artigos em Francês', 'Nesta lição, você aprenderá a identificar o gênero (masculino/feminino) e o número (singular/plural) dos substantivos em francês, além de usar corretamente os artigos definidos (le, la, les) e indefinidos (un, une, des). Este é o primeiro passo para construir frases simples e corretas.', 'Em francês, o artigo concorda em gênero e número com o substantivo. No singular: ''le'' para substantivos masculinos (ex: le livre – o livro) e ''la'' para femininos (ex: la table – a mesa). No plural, usamos ''les'' para ambos os gêneros (ex: les livres – os livros; les tables – as mesas). Os artigos indefinidos são: ''un'' (masculino singular), ''une'' (feminino singular) e ''des'' (plural). O plural dos substantivos é geralmente formado acrescentando-se um -s: ex: livre -> livres. Existem exceções, como palavras terminadas em -eau viram -eaux (ex: château -> châteaux) e -al vira -aux (ex: cheval -> chevaux).', '["Para falar de algo específico ou conhecido, use os artigos definidos: le, la, les. Exemplo: ''Je vois le chien.'' (Eu vejo o cachorro.)","Para apresentar algo pela primeira vez de maneira geral, use os artigos indefinidos: un, une, des. Exemplo: ''J''ai un chien.'' (Eu tenho um cachorro.)","Para expressar preferências gerais com verbos como ''aimer'' (gostar), use o artigo definido plural: ''J''aime les chats.'' (Eu gosto de gatos.)","No plural, o artigo definido é ''les'' e o indefinido é ''des'' para todos os gêneros. Exemplo: ''des amis'' (amigos) e ''les amis'' (os amigos)."]'::jsonb, '["Confundir o gênero dos substantivos. Exemplo incorreto: ''la livre'' (errado) – o correto é ''le livre''. Sempre aprenda a palavra com o artigo.","Esquecer de pluralizar o substantivo após o artigo plural. Exemplo incorreto: ''les livre'' (errado) – o correto é ''les livres''.","Usar artigo singular com substantivo plural. Exemplo incorreto: ''un livres'' (errado) – o correto é ''des livres''.","Não observar as exceções do plural. Exemplo incorreto: ''les chevals'' (errado) – o correto é ''les chevaux''."]'::jsonb, '["Em francês, o gênero das palavras nem sempre é previsível. Por isso, é essencial memorizar os substantivos acompanhados de seu artigo: ''le livre'', ''la chaise''.","As profissões e nacionalidades geralmente não usam artigo após o verbo ''être'': ''Je suis professeur'' (Eu sou professor), não ''Je suis un professeur''.","Para ênfase ou apresentação, pode-se usar ''c''est'' + artigo: ''C''est une actrice.'' (Ela é uma atriz.)","Cuidado com a contração de ''le'' e ''les'' com as preposições ''à'' e ''de'' (ex: au, aux, du, des), mas isso será abordado em outra lição."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

